/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A48 staging · exact frozen manifest hue–hyper (80 lemmas). */
'use strict';
const D=globalThis.RA.D;
const Q=(w,n,s,p,a,b,c,x)=>({id:`${w}.q${n}`,senseId:`${w}.s${s}`,errorType:'meaning',type:'辨义与用法',prompt:p,options:[a,b,c],answer:a,explain:x});
const M=(wrong,right,reason,type='meaning')=>({errorType:type,wrong,right,reason});
const C=(s,domain,en,zh,structure,grammar,rationale)=>({senseId:s,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline, https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:[c],mistakes:[m],quiz:qs});
P('hue','hue 经古法语 hue 进入英语，指颜色的一种色相、色调或变体。',C('hue.s1','艺术配色','The designer chose a muted blue hue for the bedroom wall so that the bright artwork would remain the focal point.','设计师为卧室墙面选了一种柔和的蓝色色调，让鲜艳的艺术品仍然成为视觉焦点。','The designer chose a muted blue hue / for the bedroom wall / so that the bright artwork / would remain the focal point.','hue 指具体颜色或色调；so that 引出配色目的。','柔和蓝色是颜色的一种色调，符合 s1。'),M('The painter described the blue hue as a kind of music rather than a shade of color.','The painter described the blue hue as a shade of color.','hue 在此表示颜色色调，不是音乐类型。'),[Q('hue',1,1,'A hue is?','a type or shade of color','a kind of shelter','a number meaning one hundred','hue 指色相、色调。'),Q('hue',2,1,'A pale green hue describes?','a particular shade of green','a loud sound','a crowded office','hue 可描述颜色的具体深浅。'),Q('hue',3,1,'Which phrase is natural?','a warm hue of red','a hundredfold hue of sound','a hibernation hue of history','hue 常与颜色搭配。'),Q('hue',4,1,'Hue is most closely related to?','color','humidity','hunting','hue 是颜色的色调。')]);
P('hug','hug 的早期词源并不确定；现代可指亲昵地拥抱、紧贴某物行驶，也可指坚持某种观点。',C('hug.s1','家庭问候','At the airport, Maya gave her grandfather a brief hug before helping him with his suitcase.','在机场，玛雅先简短地拥抱了祖父，然后帮他拿行李箱。','At the airport / Maya gave her grandfather a brief hug / before helping him / with his suitcase.','give someone a hug 表示拥抱某人；before 连接随后发生的帮助动作。','她用手臂亲昵地抱住祖父，符合 s1。'),M('Maya gave her grandfather a hug by keeping several meters between them and never touching him.','Maya waved to her grandfather from several meters away without hugging him.','保持距离且没有身体接触不构成拥抱。'),[Q('hug',1,1,'To hug someone affectionately is to?','put your arms around them','hide from them','throw something toward them','hug 可指亲昵拥抱。'),Q('hug',2,2,'A cyclist who hugs the inside of a bend?','stays very close to that side','keeps far away from the bend','stops riding entirely','hug 也可表示紧贴着行进。'),Q('hug',3,3,'To hug an idea is to?','hold firmly to that belief','forget it at once','measure its height','hug 可比喻坚持观点。'),Q('hug',4,4,'A hug is?','an act of holding someone closely','a high color tone','a number of one hundred','hug 也可作名词指拥抱。')]);
P('huge','huge 经古法语进入英语，形容尺寸、数量或重要性极大，口语中也可表示极受欢迎或成功。',C('huge.s2','社区募款','The library received a huge donation that covered the cost of new computers and weekend literacy classes.','图书馆收到了一笔巨额捐款，足以支付新电脑和周末识字课程的费用。','The library received a huge donation / that covered the cost / of new computers / and weekend literacy classes.','huge 修饰 donation，表示数量很大；that 从句说明捐款用途。','捐款足以支付多项开支，符合大量或重大的 s2。'),M('The library received a huge donation of one cent, which was too small to buy even a sheet of paper.','The library received a tiny donation of one cent, too small to buy even a sheet of paper.','一分钱金额很小，不能称为 huge donation。'),[Q('huge',1,1,'A huge building is?','extremely large in size','very small','a person who studies water','huge 可指尺寸巨大。'),Q('huge',2,2,'A huge amount of money is?','a very large amount','a tiny amount','an exact measurement of height','huge 可指数量极大。'),Q('huge',3,3,'A band that is huge informally is?','very popular or successful','physically tall only','no longer known to anyone','huge 口语中可指非常受欢迎。'),Q('huge',4,1,'The closest opposite of huge is?','tiny','enormous','massive','tiny 与 huge 相反。')]);
P('hugely','hugely 由 huge 加 -ly 构成，作副词表示程度极大或差异非常明显。',C('hugely.s1','产品影响','The low-cost filter hugely improved the village’s access to clean water, according to the independent evaluation.','独立评估指出，这种低成本过滤器极大改善了村庄获得清洁水的机会。','The low-cost filter hugely improved the village’s access / to clean water / according to the independent evaluation.','hugely 修饰 improved，表示改善程度很大；according to 引出评估来源。','过滤器使获得清洁水的条件大幅改善，符合 s1。'),M('The new filter hugely changed access to water by making no difference whatsoever.','The new filter barely changed access to water because it made no difference.','毫无影响不能称为 hugely improved。'),[Q('hugely',1,1,'Hugely means?','to an extremely great degree','only a little','in a hidden way','hugely 表示程度极大。'),Q('hugely',2,1,'If a policy hugely reduces delays, it?','reduces them by a very large amount','changes them barely at all','makes them impossible to measure','hugely 强调变化幅度很大。'),Q('hugely',3,1,'Hugely is an adverb related to?','huge','hue','hunger','hugely 由 huge 派生。'),Q('hugely',4,1,'Which phrase is natural?','hugely popular','hugely six-sided','hugely humidity','hugely 常修饰形容词或动词表示很大程度。')]);
P('hull','hull 有不同词源支系：船义指船体，种子或果实义指外层外壳；动词 hull 表示去掉外壳。',C('hull.s2','食品加工','The workers hulled the strawberries before adding them to the jam, removing the leafy tops and outer stems.','工人们在把草莓加入果酱前先去掉果蒂和外部茎叶。','The workers hulled the strawberries / before adding them to the jam / removing the leafy tops / and outer stems.','hull 作动词指去除种子或果实外层；before 表示加入果酱前的处理步骤。','草莓被去除外部果蒂，符合动词义 s2。'),M('The cook hulled the berries by wrapping each one in an intact outer shell.','The cook hulled the berries by removing their outer covering and stems.','保留并包上外壳与去掉外层相反。'),[Q('hull',1,1,'The hull of a ship is?','its main outer body','a ship’s captain','a kind of color hue','hull 可指船体。'),Q('hull',2,2,'To hull seeds is to?','remove their outer covering','plant them in soil','turn them into water','动词 hull 表示去壳。'),Q('hull',3,1,'A fruit hull is?','its dry outer case or covering','its inner juice only','a high-ranking part','hull 可指果实外壳。'),Q('hull',4,2,'Which sentence uses hull as a verb?','They hulled the berries before cooking.','The hull was damaged in the storm.','A ship has a strong hull.','hulled the berries 中 hull 作动词。')]);
P('hum','hum 是拟声词，可指闭唇哼唱、机器或昆虫发出持续低声，也可描述场所忙碌活跃。',C('hum.s2','机器检修','The refrigerator began to hum steadily after the compressor restarted, and the technician checked its temperature.','压缩机重新启动后，冰箱开始持续嗡嗡作响，技术员检查了它的温度。','The refrigerator began to hum steadily / after the compressor restarted / and the technician checked / its temperature.','hum 描述机器发出的持续低声；after 从句说明声音开始的时间。','压缩机运行时持续发出低声，符合 s2。'),M('The refrigerator hummed by making no sound at all while its motor was running.','The refrigerator ran silently while its motor was running.','完全没有声音与 hum 所指的嗡嗡声相反。'),[Q('hum',1,1,'To hum a tune is to?','sing it softly with closed lips','shout its words across a room','write it in a notebook','hum 可指闭唇哼唱。'),Q('hum',2,2,'A machine may hum by making?','a low steady sound','a sudden loud crash','a silent color change','机器 hum 指持续低鸣。'),Q('hum',3,3,'A busy café can hum with activity, meaning it?','is lively and active','is empty and silent','is under water','hum 可形容场所忙碌活跃。'),Q('hum',4,4,'A hum is?','a low continuous sound','a hiker’s map','a seed shell','hum 也可作名词指嗡嗡声。')]);
P('human','human 源自拉丁语 humanus“人的、人类的”，可作形容词描述人类，也可作名词指一个人。',C('human.s2','服务设计','The support team gave a human response to the grieving caller, allowing her time to speak instead of rushing through a script.','客服团队对悲伤的来电者作出了有人情味的回应，让她有时间表达，而没有急着照稿念完。','The support team gave a human response / to the grieving caller / allowing her time to speak / instead of rushing through a script.','human 在此表示体恤、有人情味，而非机械照本宣科；allowing 补充回应方式。','工作人员表现出对人的体恤，符合 s2。'),M('The support agent gave a human response by ignoring the caller’s distress and repeating a cold automated script.','The support agent gave a mechanical response by ignoring the caller’s distress and repeating a script.','冷漠照读脚本不是有人情味的回应。'),[Q('human',1,1,'A human problem is?','related to people or characteristic of people','a type of boat hull','a chemical element','human 可表示人的、人类的。'),Q('human',2,2,'A human response to grief is?','showing sympathy and care','following a script without noticing distress','a machine alert','human 也可指有人情味。'),Q('human',3,3,'As a noun, a human is?','a person','a habitat','a high-rise','human 可作名词指人。'),Q('human',4,1,'Human rights apply to?','people','only machines','ships','human 常表示与人类有关。')]);
P('human resources','human resources 是组织管理术语，指公司或机构中的员工，也常指负责招聘、培训和员工事务的部门。',C('human resources.s1','企业管理','Human resources surveyed the staff about training needs and shared a summary with department managers.','人力资源部门就培训需求向员工开展调查，并与各部门经理分享了摘要。','Human resources surveyed the staff / about training needs / and shared a summary / with department managers.','human resources 在此指员工事务部门；surveyed ... about 说明调查内容。','部门为员工收集培训需求，符合 s1 的企业人力资源义。'),M('Human resources refers to a company’s office furniture and has nothing to do with its workers.','Human resources refers to the people employed by an organization and the staff function that supports them.','human resources 指员工及其管理职能，不是办公家具。'),[Q('human resources',1,1,'A company’s human resources are?','the people who work for the company','its desks and computers','its roads and bridges','human resources 指公司的员工。'),Q('human resources',2,1,'The human resources department may handle?','recruiting and staff training','ship hull repairs','weather forecasting','人力资源部门常处理招聘和培训。'),Q('human resources',3,1,'Which phrase is natural?','human resources staff','human resources herring','human resources humidity','该词常用于企业人员管理。'),Q('human resources',4,1,'Human resources is often abbreviated?','HR','H2O','GPS','人力资源常缩写为 HR。')]);
P('humane','humane 源自拉丁语 humanus，形容仁慈、有同情心的，尤其指对待受苦的人或动物时不残忍。',C('humane.s2','动物照护','The shelter adopted humane handling rules that required staff to move frightened animals slowly and avoid painful restraints.','收容所采用了人道的操作规范，要求员工缓慢移动受惊动物，并避免使用会造成疼痛的束缚方式。','The shelter adopted humane handling rules / that required staff to move frightened animals slowly / and avoid painful restraints.','humane 修饰 handling rules，强调不残忍、体恤动物；that 从句说明具体规则。','规则要求减少动物受惊和疼痛，符合对待动物的人道义 s2。'),M('The shelter called its treatment humane while deliberately causing animals unnecessary pain.','The shelter called its treatment inhumane because it deliberately caused animals unnecessary pain.','故意造成不必要痛苦是不人道的。'),[Q('humane',1,1,'A humane person is?','kind and merciful toward others who suffer','deliberately cruel','a kind of fish','humane 表示仁慈、人道。'),Q('humane',2,2,'Humane treatment of animals is?','not cruel and attentive to their welfare','designed to cause avoidable pain','a type of high technology','humane 可指对待动物不残忍。'),Q('humane',3,1,'Which action is humane?','handling a frightened animal gently','punishing it by causing unnecessary pain','ignoring its injury','温和照料体现人道。'),Q('humane',4,2,'The closest opposite of humane is?','cruel','merciful','compassionate','cruel 与 humane 相反。')]);
P('humanism','humanism 经由法语、拉丁语传统而来，可指文艺复兴时期对古典人文文化的重视，也可指强调人的理性与自由的哲学。',C('humanism.s1','文艺复兴研究','The course traces Renaissance humanism through its renewed study of classical literature, history, and visual art.','这门课程通过对古典文学、历史和视觉艺术的重新研究，追溯文艺复兴人文主义。','The course traces Renaissance humanism / through its renewed study / of classical literature, history, / and visual art.','Renaissance humanism 指文艺复兴对人文文化与学问的兴趣；through 说明课程的考察路径。','例句聚焦古典文学、历史和艺术，符合 s1。'),M('The syllabus called the renewed study of Renaissance literature humanism but defined it as the study of ocean currents.','The syllabus called the renewed study of Renaissance literature humanism and defined it as an interest in human culture and learning.','humanism 此处指人文文化与学问，不是海流研究。'),[Q('humanism',1,1,'Renaissance humanism renewed interest in?','human culture, art, and learning','the chemistry of ocean currents','the breeding of livestock','文艺复兴人文主义重视人文文化与学问。'),Q('humanism',2,2,'A philosophical humanism in this entry values?','human reason and freedom','only machine efficiency','a ship’s outer shell','哲学义强调人的理性和自由。'),Q('humanism',3,1,'Which subject fits Renaissance humanism?','classical literature and art','compressor repair','humidity measurement','研究古典文学艺术属于文艺复兴人文主义。'),Q('humanism',4,2,'Humanism is a tradition concerned with?','human values and capacities','the hull of a boat','a bird’s migration only','该词关注人的价值或文化。')]);
P('humanist','humanist 是 humanism 的相关派生词，可指重视人类理性与价值的人，也可指研究文学、历史和哲学的人文学者。',C('humanist.s2','学术研究','As a humanist, Dr. Rao studies classical texts and their influence on later European history.','作为一名人文学者，拉奥博士研究古典文献及其对后世欧洲历史的影响。','As a humanist / Dr. Rao studies classical texts / and their influence / on later European history.','humanist 在此为研究人文学科的学者；as 引出身份，their 指 classical texts。','研究古典文本与历史影响属于文学、历史研究，符合 s2。'),M('Dr. Rao called herself a humanist but said she studied only hydraulic pressure and never literature, history, or philosophy.','Dr. Rao called herself a hydraulics researcher because she studied fluid pressure rather than the humanities.','此处 humanist 的学者义涉及文学、历史或哲学，不等于液压研究者。'),[Q('humanist',1,1,'A humanist who believes in human values is?','a person who values human reason and people','a gas used as fuel','a ship’s body','humanist 可指相信人类理性与价值的人。'),Q('humanist',2,2,'A humanist scholar may study?','literature, history, and philosophy','only compressor motors','only seed shells','人文学者研究文学、历史、哲学等。'),Q('humanist',3,1,'Which description fits a humanist in the belief sense?','someone who emphasizes human reason','someone who measures rainfall only','someone who removes fruit husks','该义强调人的理性。'),Q('humanist',4,2,'A university humanist is most likely a scholar of?','the humanities','hydrocarbon engines','shipbuilding alone','学者义对应人文学科。')]);
P('humanistic','humanistic 由 humanist/humanism 相关形式构成，可指基于人的理性与价值，或体现对人的需要和成长的关怀。',C('humanistic.s2','教育辅导','The adviser took a humanistic approach, asking each student about personal goals before recommending a course plan.','顾问采取以人为本的方式，在推荐课程计划前先询问每位学生的个人目标。','The adviser took a humanistic approach / asking each student about personal goals / before recommending / a course plan.','humanistic 在此表示关注人的需要和成长；asking 补充该方式的具体做法。','先了解学生个人目标体现对个人需要的关怀，符合 s2。'),M('The adviser described the approach as humanistic while refusing to learn anything about students’ needs or goals.','The adviser described the approach as impersonal because it ignored students’ needs and goals.','忽略个人需要与成长不能体现 humanistic 的人本关怀。'),[Q('humanistic',1,1,'A humanistic philosophy is based on?','human reason and values rather than religion','the weight of a ship’s hull','the amount of water vapor alone','humanistic 的 s1 义强调人的理性与价值。'),Q('humanistic',2,2,'A humanistic adviser shows?','care for people’s needs and growth','deliberate cruelty','interest only in machine noise','humanistic 也指关注人的需要和成长。'),Q('humanistic',3,2,'Which action is humanistic in this entry?','asking learners about their goals','treating them as interchangeable machines','ignoring their concerns','了解个人目标体现人本关怀。'),Q('humanistic',4,1,'Humanistic is closely related to?','humanism','hurricane','husk','humanistic 与 humanism 同词族。')]);
P('humanitarian','humanitarian 可作名词，指救助受苦者的人；也可作形容词，表示致力于援助、减轻苦难，或出于博爱。',C('humanitarian.s2','灾后援助','A humanitarian convoy delivered blankets and medical supplies to families displaced by the flood.','一支人道主义援助车队向因洪水流离失所的家庭运送了毯子和医疗用品。','A humanitarian convoy delivered blankets and medical supplies / to families / displaced by the flood.','humanitarian 修饰 convoy，表示用于救助受灾者；过去分词短语说明家庭受灾情况。','车队运送物资以帮助洪灾中的家庭，符合形容词义 s2。'),M('The convoy was called humanitarian even though it carried no aid and was organized solely to increase suffering.','The convoy was called humanitarian because it carried aid for families affected by the disaster.','以增加苦难为目的不符合 humanitarian 的援助义。'),[Q('humanitarian',1,1,'A humanitarian worker is someone who?','works to help people suffering in a crisis','repairs only ship hulls','studies color shades','名词义指帮助受苦者的人。'),Q('humanitarian',2,2,'Humanitarian aid is intended to?','help people and reduce suffering','make a disaster worse','measure a bird’s wings','形容词义强调援助和减轻苦难。'),Q('humanitarian',3,3,'A humanitarian donation made from love for people is?','charitable and benevolent','cruel and harmful','a type of gas','s3 表示博爱、慈善。'),Q('humanitarian',4,2,'Which is a humanitarian action?','providing blankets after a flood','withholding help to increase hardship','painting a wall blue','灾后提供援助符合 humanitarian。')]);
P('humanitarianism','humanitarianism 指认为人们应采取行动减轻苦难、维护人的尊严的信念或原则。',C('humanitarianism.s1','社会服务','The organization’s humanitarianism is reflected in its long-term work to protect displaced families’ dignity and meet urgent needs.','该组织的人道主义精神体现在其长期保护流离失所家庭尊严、满足紧急需求的工作中。','The organization’s humanitarianism / is reflected in its long-term work / to protect displaced families’ dignity / and meet urgent needs.','humanitarianism 是抽象名词，指人道主义信念；be reflected in 引出其体现方式。','保护尊严并缓解困境体现了减轻苦难的信念，符合 s1。'),M('The report defined humanitarianism as a belief that people should ignore suffering and deny others basic dignity.','The report defined humanitarianism as a belief that people should reduce suffering and protect human dignity.','该词指减轻苦难、维护人的尊严，而非漠视它们。'),[Q('humanitarianism',1,1,'Humanitarianism is the belief that people should?','reduce suffering and protect human dignity','increase suffering and deny dignity','keep every room humid','其核心是减轻苦难、保护尊严。'),Q('humanitarianism',2,1,'Which program reflects humanitarianism?','one that provides urgent help to displaced families','one designed to withhold all aid','one that measures color hues','援助受困者符合人道主义原则。'),Q('humanitarianism',3,1,'Humanitarianism is a?','belief or principle','bird species','ship component','它是信念或原则。'),Q('humanitarianism',4,1,'The closest related word is?','humanitarian','hydraulic','hummingbird','humanitarianism 与 humanitarian 同词族。')]);
P('humanities','humanities 指研究人类文化的学科领域，与主要研究自然现象的物理科学相对。',C('humanities.s1','大学选课','Nina chose the humanities because she wanted to study history, literature, and the ideas expressed in art.','妮娜选择了人文学科，因为她想学习历史、文学以及艺术表达的思想。','Nina chose the humanities / because she wanted to study history, literature, / and the ideas expressed in art.','humanities 作复数名词统称人文学科；because 引出她选择该领域的原因。','历史、文学和艺术思想都是研究人类文化的人文学科，符合 s1。'),M('Nina enrolled in the humanities to study only chemical reactions and the motion of planets.','Nina enrolled in the physical sciences to study chemical reactions and planetary motion.','化学反应与行星运动属于自然科学范畴，不是 humanities 的典型内容。'),[Q('humanities',1,1,'The humanities study?','human culture, such as history and literature','only the physical properties of gases','how to remove seed shells','人文学科研究人类文化。'),Q('humanities',2,1,'Which course belongs to the humanities?','a course on classical literature','a course measuring water pressure','a course on machine compressors','文学课程属于人文学科。'),Q('humanities',3,1,'Humanities are contrasted here with?','the physical sciences','human resources offices','weather shelters','词条将其与物理科学相对。'),Q('humanities',4,1,'A student in the humanities might analyze?','ideas expressed in art','the chemical formula of hydrogen only','a bird’s feeding mechanism only','艺术表达的思想属于人文研究。')]);
P('humanity','humanity 可指全体人类，也可指善良、体恤他人的品质。',C('humanity.s1','人道救援','Even during the evacuation, the neighbors showed humanity by sharing food and making room for an elderly stranger.','即使在疏散期间，邻居们仍表现出人道与善意，分享食物并为一位年长的陌生人腾出空间。','Even during the evacuation / the neighbors showed humanity / by sharing food / and making room for an elderly stranger.','humanity 在此指善良、体恤他人的品质；by 引出表现善意的方式。','分享食物并照顾陌生人体现了人的善意，符合 s1 的 kindness 义。'),M('The neighbors showed humanity by refusing all help to a hungry stranger solely to make the evacuation harder.','The neighbors showed cruelty by refusing all help to a hungry stranger.','拒绝援助且故意增加困难不能体现 humanity 的善意义。'),[Q('humanity',1,1,'Humanity can mean?','all people or kindness','only a type of machine','a measure of humidity','humanity 有“人类”或“人道、善意”两义。'),Q('humanity',2,1,'A person who treats a stranger kindly shows?','humanity','a ship hull','a color hue','善待他人体现 humanity。'),Q('humanity',3,1,'The future of humanity means the future of?','all human beings','all seed coverings','one bird species','此处 humanity 指全体人类。'),Q('humanity',4,1,'Which quality is closest to humanity in the kindness sense?','compassion','cruelty','gaseousness','善意与 compassion 接近。')]);
P('humankind','humankind 是集合名词，指作为整体的所有人类。',C('humankind.s1','全球合作','The report argues that humankind must cooperate across borders to protect shared ecosystems.','报告认为，全人类必须跨越国界合作，保护共同的生态系统。','The report argues / that humankind must cooperate across borders / to protect shared ecosystems.','humankind 作集合名词，通常按整体看待；that 引出报告的主张。','跨国合作的主体是全体人类，符合 s1。'),M('The report used humankind to mean a single computer program rather than all people.','The report used humankind to mean all people considered together.','humankind 指全体人类，不是软件程序。'),[Q('humankind',1,1,'Humankind means?','all humans considered together','one individual bird','a machine’s low sound','humankind 指全人类。'),Q('humankind',2,1,'A challenge facing humankind affects?','people as a whole','only one seed shell','only a ship’s body','该词把人类作为整体。'),Q('humankind',3,1,'Which word is closest in meaning?','humanity','hull','hurdle','humanity 可表示全体人类。'),Q('humankind',4,1,'Humankind is best treated as?','a collective noun for all people','a verb meaning to hurry','an adjective for damp air','它是全体人类的集合名词。')]);
P('humanlike','humanlike 由 human 与 -like 构成，表示在外表或行为上类似人类。',C('humanlike.s1','机器人设计','The museum’s robot has humanlike hands, but its stiff movements make its mechanical nature obvious.','博物馆的机器人有类似人类的手，但僵硬的动作明显暴露了它的机械本质。','The museum’s robot has humanlike hands / but its stiff movements / make its mechanical nature obvious.','humanlike 表示“像人的、类似人类的”，不表示真实的人；but 引出外观和动作的反差。','机器人的手在形状上像人手，符合 appearance 相似的 s1。'),M('The exhibit called the robot humanlike because it was an ordinary human visitor rather than a machine.','The exhibit called the robot humanlike because its design resembled a person’s.','humanlike 表示相似，不等于本身就是人。'),[Q('humanlike',1,1,'A humanlike face is?','similar in appearance to a person’s face','a face belonging to a ship','a face with a particular blue hue','humanlike 表示外观类似人类。'),Q('humanlike',2,1,'A robot that waves like a person may act?','in a humanlike way','in a hydrographic way','in a seed-covering way','行为类似人也可用 humanlike。'),Q('humanlike',3,1,'Does humanlike necessarily mean “human”?','No, it means similar to a human.','Yes, it always means a real person.','No, it means a type of storm.','-like 表示相似，而非等同。'),Q('humanlike',4,1,'The suffix -like in humanlike means?','similar to','made from water','without people','-like 表示“像……的”。')]);
P('humanness','humanness 指使某种存在具有“人”的特征，例如感受能力和道德意识。',C('humanness.s1','人工智能伦理','The novel explores the humanness of its artificial character through her capacity for grief, empathy, and moral choice.','这部小说通过人工角色感受悲伤、共情和作出道德选择的能力，探讨了她的人性。','The novel explores the humanness / of its artificial character / through her capacity for grief, empathy, / and moral choice.','humanness 是抽象名词，指人的特质；through 引出作品呈现这些特质的途径。','悲伤、共情和道德选择都是人性的表现，符合 s1。'),M('The essay defined humanness as the ability to calculate numbers with no feelings or moral awareness.','The essay defined humanness as qualities such as feeling and moral awareness.','单纯计算能力不能充分代表该词所指的人性特征。'),[Q('humanness',1,1,'Humanness refers to?','qualities that make a being human','the outer case of a fruit','a type of low machine sound','humanness 指人性或为人的特质。'),Q('humanness',2,1,'Which pair can express humanness?','feeling and moral sense','humidity and air pressure','hull and rudder','情感与道德意识可体现人性。'),Q('humanness',3,1,'Humanness is an?','abstract noun','adverb meaning hugely','animal name','它是表示特质的抽象名词。'),Q('humanness',4,1,'A story explores a character’s humanness by showing?','her empathy and moral choices','only the color of her clothes','the dimensions of a ship','共情和道德选择体现人性。')]);
P('humans','humans 是 human 的复数形式，表示人、人类个体。',C('humans.s1','野生动物保护','The field study observed how humans and local wildlife shared the edge of the wetland.','这项实地研究观察了人类与当地野生动物如何共享湿地边缘。','The field study observed / how humans and local wildlife / shared the edge / of the wetland.','humans 是 human 的复数形式；how 从句说明研究观察的内容。','句中 humans 与 wildlife 并列，指多个人类个体，符合 s1。'),M('The article used humans for one person and human for several people.','The article used human for one person and humans for more than one person.','humans 是复数，不能用来表示单数一个人。'),[Q('humans',1,1,'Humans is the plural of?','human','humanity','hue','humans 是 human 的复数。'),Q('humans',2,1,'If several humans enter a room, how many people enter?','more than one','exactly zero','only one','复数形式表示不止一个人。'),Q('humans',3,1,'Which sentence uses humans correctly?','Humans depend on clean water.','One humans is waiting.','The humans means one person only.','复数主语 Humans 可搭配 depend。'),Q('humans',4,1,'The singular form is?','human','humankindness','humanities','human 是 humans 的单数形式。')]);
P('humble','humble 源于拉丁语 humilis“低的、谦逊的”，可形容谦虚、地位低或朴素，也可作动词使人谦卑。',C('humble.s1','获奖感言','The scientist remained humble after receiving the award and credited the laboratory team for the discovery.','这位科学家获奖后仍很谦逊，并将这项发现归功于实验室团队。','The scientist remained humble / after receiving the award / and credited the laboratory team / for the discovery.','humble 在此表示谦逊；after 引出获奖之后的表现。','她不把荣誉全归于自己，体现 s1 的谦逊义。'),M('After the award, the scientist called herself humble while insisting that no colleague had contributed anything.','After the award, the scientist showed humility by acknowledging her colleagues’ contributions.','否认同事贡献、夸大个人功劳与谦逊相矛盾。'),[Q('humble',1,1,'A humble person does not think they are?','better than everyone else','capable of learning','part of humankind','humble 的 s1 义是不自认为高人一等。'),Q('humble',2,2,'A humble background may mean?','low social rank or position','extreme popularity','a high level of humidity','humble 也可指出身或地位不高。'),Q('humble',3,3,'A humble cottage is likely?','simple and not expensive','huge and luxurious','a chemical compound','humble 可形容简朴、不昂贵。'),Q('humble',4,4,'To humble someone is to?','make them feel less proud','give them a color shade','increase the water vapor in a room','动词 humble 可指使人谦卑。')]);
P('humbleness','humbleness 由 humble 加名词后缀构成，指对自身重要性持谦逊看法的品质。',C('humbleness.s1','团队合作','Her humbleness was clear when she welcomed questions and openly credited the colleagues who had helped with the project.','她乐于接受提问，并坦率感谢参与项目的同事，这体现了她的谦逊。','Her humbleness was clear / when she welcomed questions / and openly credited the colleagues / who had helped with the project.','humbleness 是名词，指谦逊的品质；when 引出表现该品质的行为。','她愿意承认团队贡献，体现谦逊而非自我抬高。'),M('His humbleness showed when he claimed that every achievement belonged to him alone.','His arrogance showed when he claimed that every achievement belonged to him alone.','独占全部功劳体现傲慢，不是 humbleness。'),[Q('humbleness',1,1,'Humbleness is?','a modest view of one’s own importance','a belief that one is always superior','a type of storm','humbleness 指谦逊。'),Q('humbleness',2,1,'Which behavior shows humbleness?','crediting teammates for shared work','claiming every success alone','mocking everyone who asks a question','承认团队贡献体现谦逊。'),Q('humbleness',3,1,'Humbleness is a noun related to?','humble','humbug','humidity','humbleness 由 humble 派生。'),Q('humbleness',4,1,'The opposite of humbleness is closest to?','arrogance','modesty','consideration','arrogance 与谦逊相反。')]);
P('humdrum','humdrum 形容因缺乏变化而普通、乏味，也可作名词指单调日常。',C('humdrum.s1','工作日常','After months of the same humdrum schedule, Lena began taking a different route to work and learning a new skill.','连续几个月过着同样单调乏味的日程后，莉娜开始换一条路线通勤，并学习一项新技能。','After months of the same humdrum schedule / Lena began taking a different route / to work / and learning a new skill.','humdrum 修饰 schedule，强调因缺乏变化而乏味；after 引出改变前的状态。','日程数月如一日，符合 s1 的单调乏味义。'),M('The humdrum routine was exciting because every day brought a completely new surprise.','The humdrum routine was dull because every day followed the same pattern.','每天都有全新惊喜与 humdrum 所指的缺少变化不符。'),[Q('humdrum',1,1,'A humdrum week is?','ordinary and boring because little changes','full of unexpected adventures','made of a hundred parts','humdrum 强调普通、乏味、缺乏变化。'),Q('humdrum',2,2,'The humdrum of daily life refers to?','a dull routine','a sudden hurricane','a joyful celebration','名词义指单调日常。'),Q('humdrum',3,1,'Which schedule sounds humdrum?','the same tasks in the same order every day','a different expedition each morning','a constantly changing festival','反复不变的任务容易显得 humdrum。'),Q('humdrum',4,1,'A close synonym for humdrum is?','monotonous','thrilling','humanitarian','monotonous 表示单调乏味。')]);
P('humid','humid 描述空气含有较多水汽，也可说气候潮湿闷热。',C('humid.s2','气候观察','The coastal town has a humid climate, with warm damp air lingering well into the evening.','这座海滨小镇气候湿热，温暖潮湿的空气一直持续到傍晚。','The coastal town has a humid climate / with warm damp air / lingering well into the evening.','humid 修饰 climate，表示潮湿闷热的气候；with 短语补充其空气特征。','温暖而潮湿的空气符合 s2。'),M('The forecast described the desert afternoon as humid even though the air contained almost no moisture.','The forecast described the desert afternoon as dry because the air contained almost no moisture.','几乎没有水汽的空气应为干燥，不能称为 humid。'),[Q('humid',1,1,'Humid air contains?','a lot of water vapor','almost no moisture','only solid ice','humid 描述空气水汽较多。'),Q('humid',2,2,'A humid climate is often?','damp and warm','cold and completely dry','noisily active','s2 描述潮湿温暖的气候。'),Q('humid',3,1,'Which place is most likely humid?','a warm coastal region with damp air','a dry room with no moisture','a frozen vacuum','潮湿空气多见于湿润地区。'),Q('humid',4,1,'The opposite of humid is usually?','dry','damp','moist','dry 表示干燥，与 humid 相对。')]);
P('humidify','humidify 是动词，表示增加某物尤其是空气中的水汽含量。',C('humidify.s1','室内环境','A small device can humidify the nursery during winter, when indoor heating makes the air uncomfortably dry.','冬季室内供暖使空气干燥、不舒服时，小型设备可以给婴儿房加湿。','A small device can humidify the nursery / during winter / when indoor heating makes the air / uncomfortably dry.','humidify 为及物动词，表示给空气增加水汽；when 引出使用场景。','设备增加室内空气水汽，符合 s1。'),M('The machine humidified the room by removing water vapor and making the air even drier.','The machine dehumidified the room by removing water vapor and making the air drier.','移除水汽是除湿，不是 humidify。'),[Q('humidify',1,1,'To humidify a room is to?','add moisture to its air','remove all water vapor','make it a hundred times larger','humidify 表示加湿。'),Q('humidify',2,1,'A humidifier may be used when indoor air is?','too dry','already underwater','full of solid metal','干燥空气可通过加湿器增加水分。'),Q('humidify',3,1,'Which verb is closest to humidify?','moisten','dehydrate','hurl','moisten 意为弄湿，与 humidify 接近。'),Q('humidify',4,1,'Humidify is a?','verb','plural noun for people','name for a whale','humidify 是动词。')]);
P('humidity','humidity 指空气中水汽的含量，也可指人在某处感受到的潮湿。',C('humidity.s1','天气预报','The weather app showed high humidity, so the runner chose a shaded route and carried water.','天气应用显示湿度较高，因此跑步者选择了有遮阴的路线并带上饮用水。','The weather app showed high humidity / so the runner chose a shaded route / and carried water.','humidity 是空气中水汽含量；so 引出高湿度下采取的安排。','天气应用测得空气水汽含量较高，符合 s1。'),M('The report said humidity was zero because the air was saturated with water vapor.','The report said humidity was high because the air was saturated with water vapor.','空气饱含水汽意味着湿度高，不是零。'),[Q('humidity',1,1,'Humidity measures?','the amount of water vapor in air','the number of people at work','the color of a ship','humidity 指空气中的水汽含量。'),Q('humidity',2,2,'A room that feels damp may have high?','humidity','humbleness','hull','潮湿感可称为 humidity。'),Q('humidity',3,1,'Which instrument reading concerns humidity?','a measure of moisture in the air','a count of hurdles in a race','a measure of how many people are humanists','空气湿度读数反映水汽含量。'),Q('humidity',4,1,'High humidity usually means air is?','moist','bone-dry','silent','较高 humidity 意味空气较潮湿。')]);
P('humiliate','humiliate 可指当众使某人难堪、蒙羞，也可指使人感到不如人、失去自尊。',C('humiliate.s1','职场沟通','The manager corrected the spreadsheet privately rather than humiliate the new employee in front of the team.','经理选择私下更正电子表格，而不是当着团队的面让新员工难堪。','The manager corrected the spreadsheet privately / rather than humiliate the new employee / in front of the team.','humiliate 作动词，表示使人当众难堪；rather than 表明选择避免这种做法。','公开羞辱员工会使其难堪，私下纠正则避免 humiliate。'),M('The manager humiliated the employee by praising her privately and protecting her dignity.','The manager encouraged the employee by praising her privately and protecting her dignity.','保护尊严并私下表扬不是羞辱。'),[Q('humiliate',1,1,'To humiliate someone publicly is to?','embarrass and shame them','praise them quietly','give them a shelter','humiliate 表示使人难堪、蒙羞。'),Q('humiliate',2,2,'A remark that makes someone feel less worthy may?','humiliate them','humidify them','hull them','s2 强调使人自卑或蒙羞。'),Q('humiliate',3,1,'Which choice avoids humiliating a colleague?','offer correction privately and respectfully','mock their mistake before the whole team','share their mistake for amusement','公开嘲弄容易使人受辱。'),Q('humiliate',4,1,'A close opposite of humiliate is?','respect','shame','embarrass','respect 与羞辱相反。')]);
P('humility','humility 是不把自己看得高人一等的品质，即谦卑、谦虚。',C('humility.s1','科学协作','With humility, the lead researcher described the result as preliminary and invited other teams to test it.','首席研究员谦逊地将结果称为初步发现，并邀请其他团队进行检验。','With humility / the lead researcher described the result as preliminary / and invited other teams / to test it.','humility 是抽象名词，表示谦逊；with 引出做事的态度。','承认结果暂定并欢迎复核，体现不自视过高的 humility。'),M('He showed humility by declaring that no one else was intelligent enough to question his conclusions.','He showed arrogance by declaring that no one else was intelligent enough to question his conclusions.','认为无人能质疑自己体现傲慢，不是 humility。'),[Q('humility',1,1,'Humility is the quality of?','not thinking oneself better than others','claiming to be superior to everyone','being full of water vapor','humility 指不自认为高人一等。'),Q('humility',2,1,'Which response shows humility?','calling a result preliminary and welcoming review','insisting one cannot be wrong','taking credit for every teammate’s work','欢迎检验且承认局限体现谦逊。'),Q('humility',3,1,'Humility is most closely related to?','modesty','arrogance','humidity','modesty 与谦逊接近。'),Q('humility',4,1,'The suffix-like ending in humility forms a?','noun naming a quality','verb meaning to throw','plural for human','humility 是表示品质的名词。')]);
P('hummingbird','hummingbird 是一种以花蜜为食的小型鸟，能够悬停，甚至向后飞。',C('hummingbird.s1','庭院观察','A hummingbird hovered beside the red blossoms, then darted backward before visiting another flower.','一只蜂鸟在红花旁悬停，随后向后飞开，又去访问另一朵花。','A hummingbird hovered beside the red blossoms / then darted backward / before visiting another flower.','hummingbird 是名词；hovered 与 backward 描述蜂鸟特有的飞行动作。','小型鸟在花旁悬停并向后飞，符合 s1。'),M('The guide called the hovering nectar-feeding bird a hummingbird but said it was a large freshwater fish.','The guide called the hovering nectar-feeding bird a hummingbird, a small bird rather than a fish.','hummingbird 是鸟类，不是淡水鱼。'),[Q('hummingbird',1,1,'A hummingbird is a?','tiny nectar-feeding bird','large freshwater fish','kind of ship','hummingbird 指蜂鸟。'),Q('hummingbird',2,1,'What unusual movement can a hummingbird make?','hover and fly backward','run a hurdle race','swim under ice','蜂鸟能够悬停并向后飞。'),Q('hummingbird',3,1,'A hummingbird is likely to visit?','flowers for nectar','a ship’s engine room','a dry seed shell only','蜂鸟常吸食花蜜。'),Q('hummingbird',4,1,'Which description best fits its size?','very small','larger than a hurricane','the size of a house','词条将其描述为 tiny。')]);
P('humor','humor 可指有趣、逗乐的特质或幽默作品，也可指心情，还可作动词表示迁就某人。',C('humor.s4','家庭协商','Mina humored her little brother by listening to his long story about toy trains before bedtime.','睡前，米娜耐心听弟弟讲了很久的玩具火车故事，顺着他的心意。','Mina humored her little brother / by listening to his long story / about toy trains / before bedtime.','humor 作动词表示迁就、哄某人开心；by 引出她迁就弟弟的做法。','她按弟弟的心意听故事使他开心，符合 s4。'),M('Mina humored her brother by refusing to hear him and insisting that his feelings did not matter.','Mina ignored her brother rather than humor him by listening to his story.','拒绝倾听不属于为使对方开心而迁就。'),[Q('humor',1,1,'Humor in a joke is?','the quality of being funny','a ship’s outside body','a degree of moisture','humor 的 s1 指幽默或滑稽。'),Q('humor',2,2,'A writer’s humor may refer to?','a style of comedy or funny writing','a bird’s wings','a number column','humor 可指一种幽默作品或风格。'),Q('humor',3,3,'Someone in a cheerful humor is in a particular?','state of mind','type of climate','kind of shelter','humor 也可指心情、情绪。'),Q('humor',4,4,'To humor a child is to?','go along with what they want to keep them happy','publicly shame them','measure the air’s moisture','动词 humor 可表示迁就、哄某人。')]);
P('humorist','humorist 指创作幽默作品或以逗趣写作为业的人。',C('humorist.s1','文学介绍','The humorist turned small inconveniences into gentle stories that made readers laugh without mocking anyone.','这位幽默作家把小小的不便写成温和的故事，让读者发笑而不嘲弄任何人。','The humorist turned small inconveniences into gentle stories / that made readers laugh / without mocking anyone.','humorist 是创作幽默作品的人；that 从句说明作品产生的效果。','她把日常不便写成有趣故事，符合 s1。'),M('The review called the humorist a writer of funny stories but then said he never wrote or created anything.','The review called the humorist a writer of funny stories.','humorist 指创作幽默作品的人；说其从未写作自相矛盾。'),[Q('humorist',1,1,'A humorist is someone who?','writes funny works','studies humidity only','repairs ship hulls','humorist 指幽默作家。'),Q('humorist',2,1,'A humorist might publish?','comic essays or amusing stories','a weather forecast only','a chemical formula only','幽默作品可能是诙谐散文或故事。'),Q('humorist',3,1,'The word humorist is related to?','humor','hurricane','husk','humorist 与 humor 同词族。'),Q('humorist',4,1,'A humorist aims to make readers?','laugh or smile','feel only physical pain','measure a hundred objects','幽默作家常以逗乐读者为目标。')]);
P('humorous','humorous 表示有趣、诙谐，或能够看出事情可笑的一面。',C('humorous.s1','日常写作','The guide included a humorous footnote about the museum’s unusually persistent office cat.','导览手册里有一条幽默的脚注，讲的是博物馆那只异常执着的办公室猫。','The guide included a humorous footnote / about the museum’s unusually persistent / office cat.','humorous 修饰 footnote，表示其内容有趣；about 引出趣味主题。','脚注以轻松方式描述办公室猫，符合 amusing 的 s1。'),M('The supposedly humorous footnote insulted a visitor and contained no joke or amusing detail.','The insulting footnote was offensive rather than humorous.','若内容只含侮辱、没有可笑或逗趣之处，就不适合称为 humorous。'),[Q('humorous',1,1,'A humorous remark is?','amusing or funny','extremely damp','a hundred times larger','humorous 表示有趣、诙谐。'),Q('humorous',2,1,'Which note is humorous?','a gentle joke about a cat’s habits','a dry list of measurements','an insulting threat','轻松的猫咪趣事具有幽默感。'),Q('humorous',3,1,'Humorous is an?','adjective','adverb for humidity','plural noun','humorous 是形容词。'),Q('humorous',4,1,'A humorous person may be able to?','see the funny side of a situation','remove a fruit’s hull','measure water pressure','humorous 也可指能看出事情有趣一面。')]);
P('humorously','humorously 是副词，表示以逗趣的方式表达，而非单纯刻薄或伤人。',C('humorously.s1','演讲表达','The speaker humorously compared the crowded bus to a moving puzzle, and the passengers laughed with her.','演讲者幽默地把拥挤的公交车比作一幅移动的拼图，乘客们也跟着笑了。','The speaker humorously compared the crowded bus / to a moving puzzle / and the passengers laughed / with her.','humorously 修饰 compared，说明比喻的表达方式；with her 表示大家一起发笑。','这个比喻让乘客会心一笑而非遭到嘲弄，符合 s1。'),M('He spoke humorously by targeting one passenger with a cruel insult that made everyone else uncomfortable.','He spoke cruelly by targeting one passenger with a hurtful insult.','刻薄侮辱令人不适，不是以逗趣方式表达。'),[Q('humorously',1,1,'Humorously means?','in a way that amuses','in a completely silent way','in a manner that removes moisture','humorously 表示幽默地。'),Q('humorously',2,1,'A humorously phrased comparison should?','amuse without merely being cruel','hurt a listener on purpose','report humidity exactly','词条强调逗趣而非刻薄。'),Q('humorously',3,1,'In a sentence, humorously most naturally modifies?','a verb such as described','a plural human noun only','the number one hundred','副词 humorously 可修饰动作动词。'),Q('humorously',4,1,'Which phrase is natural?','humorously tell a story','humorously water vapor','humorously three hulls','humorously 可修饰 tell 等表达动作。')]);
P('humourous','humourous 是 humour 的相关形容词拼法，表示有趣或倾向于看到事情幽默的一面。',C('humourous.s1','英式拼写阅读','In the British edition, the reviewer called the author’s short sketches humourous and warm-hearted.','在英国版评论中，评论者称这位作者的短篇小品诙谐又温暖。','In the British edition / the reviewer called the author’s short sketches / humourous and warm-hearted.','humourous 在此作形容词，表示诙谐；British edition 提示采用 humour 拼法的语境。','评论描述作品诙谐、温暖，符合 s1；该拼法是可用变体，不应误判为错字。'),M('The editor marked humourous as a spelling error solely because it uses the British spelling humour.','The editor accepted humourous as a variant spelling related to humour.','humourous 是可用拼法变体，不能只因采用 humour 拼法就判错。','usage'),[Q('humourous',1,1,'Humourous means?','amusing or inclined to see the funny side','filled with water vapor','a kind of seed covering','humourous 表示诙谐、有幽默感。'),Q('humourous',2,1,'Which statement is accurate?','Humourous is a valid spelling variant.','Humourous is always a typo.','It means a tropical storm.','humourous 是有效拼法，不应误判为错字。'),Q('humourous',3,1,'A humourous sketch is likely to be?','funny or amusing','painful and cruel by definition','a scientific water chart','该形容词描述有趣作品。'),Q('humourous',4,1,'The spelling humourous is associated with the form?','humour','hull','hurricane','该拼法保留 humour 中的 u。')]);
P('hump','hump 可指骆驼背部或地面上的大圆形隆起，也可作动词表示弓背或费力搬运。',C('hump.s2','搬运行李','We had to hump the heavy boxes up two flights of stairs because the service lift was out of order.','由于货运电梯停用，我们只好费力把沉重的箱子搬上两层楼。','We had to hump the heavy boxes / up two flights of stairs / because the service lift / was out of order.','hump 作动词表示费力搬运；had to 表示因电梯故障而不得不这样做。','箱子很重，需要费力搬上楼，符合 s2。'),M('They humped the boxes upstairs by leaving them untouched on the ground floor.','They left the boxes downstairs instead of humping them upstairs.','把箱子留在原处并未搬运，与 hump 的动作矛盾。'),[Q('hump',1,1,'A camel’s hump is?','a large rounded lump on its back','a small song hummed softly','a type of fruit juice','hump 可指背部的隆起。'),Q('hump',2,2,'To hump a heavy box upstairs is to?','carry it with effort','paint it a blue hue','make it more humid','动词义指费力搬运。'),Q('hump',3,1,'A hump on a road may be?','a raised rounded part','a flat hole','a weather report','hump 也可指地面上的隆起。'),Q('hump',4,2,'Which sentence uses hump as a verb?','They humped the cases up the steps.','A camel has a hump.','The hump was visible from far away.','humped cases 表示费力搬运箱子。')]);
P('humpback','humpback 可指向外隆起的驼背，也可指背鳍前有小隆起、长鳍显著的大型座头鲸。',C('humpback.s2','海洋观察','Researchers identified a humpback by its long flippers and the small hump in front of its dorsal fin.','研究人员根据长长的胸鳍和背鳍前的小隆起辨认出一头座头鲸。','Researchers identified a humpback / by its long flippers / and the small hump / in front of its dorsal fin.','humpback 在此作鲸类名称；by 引出用于辨认的身体特征。','长鳍及背鳍前的隆起符合座头鲸特征，指 s2。'),M('The field guide identified the humpback as a tiny seed-eating bird.','The field guide identified the humpback as a large whale.','humpback 的该义是大型鲸类，不是小型鸟。'),[Q('humpback',1,1,'A humpback in the whale sense is a?','large whale with long flippers','tiny nectar-feeding bird','small freshwater insect','humpback 可指座头鲸。'),Q('humpback',2,2,'A humpback back is one that?','curves outward in a hump','is perfectly flat','contains much water vapor','s1 指向外弯曲隆起的背部。'),Q('humpback',3,2,'Which is a respectful use of the body-description sense?','The medical note described an outward curve of the back.','The speaker used it to mock a person.','The label called a whale a seed shell.','描述身体特征应客观而尊重。'),Q('humpback',4,1,'A humpback whale can be recognized by?','long flippers and a small hump near its dorsal fin','a hundred legs','a dry outer seed case','词条列出的特征包括长鳍和背鳍前的小隆起。')]);
P('hunch','hunch 可作名词表示尚无确证的直觉，也可作动词表示弯腰、耸肩。',C('hunch.s1','案件调查','I had a hunch that the missing folder was in the archive room, so I checked the catalog before searching.','我隐约觉得丢失的文件夹在档案室，于是在寻找之前先查了目录。','I had a hunch / that the missing folder was in the archive room / so I checked the catalog / before searching.','hunch 在此作名词，指尚未证实的直觉；that 从句说明直觉内容。','说话者有猜测并去核查，符合“预感”义 s1。'),M('She called it a hunch even though she had already confirmed the folder’s location with a signed receipt.','She called it a confirmed fact because a signed receipt proved the folder’s location.','已有直接证据确认时称为事实，不是未证实的 hunch。'),[Q('hunch',1,1,'A hunch is?','a feeling or guess without firm proof','a measured humidity reading','the body of a ship','hunch 可指预感。'),Q('hunch',2,1,'If you have a hunch the keys are upstairs, you?','suspect they may be there','know their location with certainty','have thrown them forcefully','hunch 表示尚待核实的直觉。'),Q('hunch',3,1,'To hunch over a desk is to?','bend forward over it','stand completely upright','walk backward like a bird','hunch 也可作动词表示弯腰。'),Q('hunch',4,1,'Which action might follow a hunch?','checking whether your guess is correct','treating an untested guess as a guarantee','measuring a ship’s hull','直觉可以促使人进一步核查。')]);
P('hundred','hundred 是基数词“一百”，也可指一百个或数以百计的数量。',C('hundred.s2','志愿者招募','The center printed a hundred information cards for visitors and kept the extras at the front desk.','中心为访客印制了一百张信息卡，并把多余的卡片放在前台。','The center printed a hundred information cards / for visitors / and kept the extras / at the front desk.','a hundred 修饰复数名词 cards，表示一百张；extras 指多印的卡片。','句中表示一百张卡片，符合 s2。'),M('The poster said a hundred volunteers had arrived, but it showed only one person and gave no sign of a larger group.','The poster said one volunteer had arrived, matching the single person shown.','一个人不能表述为一百人。'),[Q('hundred',1,1,'Hundred is the number?','100','10','1,000','hundred 的基数词义是一百。'),Q('hundred',2,2,'A hundred cards means?','100 cards','10 cards','one card only','a hundred of something 表示一百个。'),Q('hundred',3,3,'Hundreds of visitors suggests?','a large number, several hundred','exactly one visitor','no visitors','复数 hundreds 可泛指数百、很多。'),Q('hundred',4,1,'In 483, the hundreds column contains?','4','8','3','483 的百位数字是 4。')]);
P('hundredfold','hundredfold 表示数量乘以一百的，也可作副词表示增加或减少一百倍。',C('hundredfold.s2','实验比较','The revised sensor detected the weak signal a hundredfold more clearly than the older model.','与旧型号相比，改进后的传感器对微弱信号的检测清晰度提高了一百倍。','The revised sensor detected the weak signal / a hundredfold more clearly / than the older model.','a hundredfold 作副词修饰 more clearly，表示一百倍的程度；than 引出比较对象。','比较的是检测清晰度提高百倍，符合 s2。'),M('The report called a change hundredfold even though the measured value increased by only one percent.','The report called a one-percent change slight rather than hundredfold.','百分之一的变化并非一百倍增长。'),[Q('hundredfold',1,1,'A hundredfold increase means the amount is?','multiplied by one hundred','reduced to one hundredth','unchanged','hundredfold 表示乘以一百。'),Q('hundredfold',2,2,'If a signal improves hundredfold, it improves?','by a factor of 100','by a factor of 2','not at all','副词义表示一百倍。'),Q('hundredfold',3,1,'Which change is hundredfold?','2 becoming 200','2 becoming 4','2 staying 2','2 乘以一百得到 200。'),Q('hundredfold',4,2,'Hundredfold can describe?','a hundred-times difference','a single color shade','a low continuous hum','该词表示百倍关系。')]);
P('hunger','hunger 可指需要食物的饥饿、长期缺粮，也可表示强烈愿望或作动词渴望。',C('hunger.s3','求知愿望','Her hunger for knowledge led her to attend evening classes and borrow books from the public library.','她对知识的渴望促使她参加夜校，并从公共图书馆借书。','Her hunger for knowledge / led her to attend evening classes / and borrow books / from the public library.','hunger for 是固定搭配，表示对某物的强烈渴望；led to 说明其结果。','她持续追求学习，符合 s3 的渴望义。'),M('He described his hunger for knowledge but refused to read, ask questions, or learn anything new.','He showed little hunger for knowledge because he avoided reading or learning.','拒绝学习的行为与强烈求知欲不相符。'),[Q('hunger',1,1,'Hunger can mean?','the feeling of needing food','a type of whale','a hundredfold change','hunger 的基本义是饥饿感。'),Q('hunger',2,2,'A country facing hunger over many years may suffer from?','a long-term lack of food','high humidity','too many hurdles','长期缺粮可称为饥荒。'),Q('hunger',3,3,'A hunger for justice is?','a strong desire for justice','a need to eat justice','a low sound','hunger for 可表示强烈愿望。'),Q('hunger',4,4,'To hunger for change is to?','want change very strongly','feel no interest in change','carry change upstairs','动词 hunger 可表示渴望。')]);

P('hungry','hungry 可表示需要或想吃东西，也可与 for 连用表示强烈渴望。',C('hungry.s1','长途步行','After the long walk, the children were hungry and eagerly ate the sandwiches prepared for the trip.','长途步行后，孩子们饿了，便迫不及待地吃起为旅程准备的三明治。','After the long walk / the children were hungry / and eagerly ate the sandwiches / prepared for the trip.','hungry 作表语形容词，表示想吃东西；after 引出饥饿出现的情境。','长途步行后需要进食，符合 s1。'),M('The hikers said they were hungry but had just eaten a large meal and did not want any food.','The hikers said they were full after eating a large meal.','刚吃饱且不想吃东西与 hungry 的进食需求不符。'),[Q('hungry',1,1,'A hungry person?','needs or wants to eat','has just eaten enough and wants no food','is a kind of plant','hungry 表示饥饿的。'),Q('hungry',2,2,'Hungry for success means?','strongly desiring success','needing to eat success','being indifferent to success','hungry for 可表示渴望。'),Q('hungry',3,1,'After skipping lunch, someone may feel?','hungry','humble','hydraulic','没有午餐后容易感到饥饿。'),Q('hungry',4,2,'Which phrase is natural?','hungry for a chance to learn','hungry humidity of a chance','hungry hull a chance','hungry for 可表达强烈愿望。')]);
P('hunt','hunt 可指追逐并猎捕动物、急切搜寻物品，也可指追捕某人；作名词时还可指狩猎活动。',C('hunt.s2','档案检索','The archivist hunted through several boxes for the original map, checking each folder against the catalog.','档案管理员在几箱材料中仔细搜寻原始地图，并把每个文件夹与目录核对。','The archivist hunted through several boxes / for the original map / checking each folder / against the catalog.','hunt through ... for ... 表示在某处仔细寻找某物；checking 补充搜索方法。','管理员在档案中急切、仔细地找地图，符合 s2。'),M('She hunted for the map by refusing to look in any box or consult the catalog.','She searched the boxes and catalog for the map.','不检查任何材料就不能称为仔细搜寻。'),[Q('hunt',1,1,'To hunt wild animals is to?','chase and kill them','feed them indoors','draw their portraits','hunt 的 s1 是追逐并猎捕动物。'),Q('hunt',2,2,'To hunt for a missing key is to?','search eagerly for it','hide it deliberately','measure its weight','hunt for 可表示搜寻。'),Q('hunt',3,3,'Police may hunt a suspect to?','chase and catch them','teach them to hum','remove their coat','hunt 也可指追捕罪犯或嫌疑人。'),Q('hunt',4,4,'A hunt can be?','an activity of hunting','a color shade','a kind of seed cover','hunt 可作名词指狩猎活动。')]);
P('hunter','hunter 是由 hunt 加施事者后缀 -er 构成的名词，指猎捕动物的人。',C('hunter.s1','野外观察','The hunter followed local regulations, recorded the location of the tracks, and left the protected area undisturbed.','猎人遵守当地规定，记录了足迹的位置，并让保护区保持原状。','The hunter followed local regulations / recorded the location of the tracks / and left the protected area / undisturbed.','hunter 指猎人；并列谓语 follow、record、leave 描述其行为。','遵守狩猎规范并追踪动物足迹的人符合 s1。'),M('The article called a person who repairs refrigerators for a living a hunter.','The article called a person who pursues wild animals a hunter.','修冰箱与猎捕动物无关，不能据此称为 hunter。'),[Q('hunter',1,1,'A hunter is someone who?','hunts animals','writes jokes professionally','studies human culture only','hunter 指猎人。'),Q('hunter',2,1,'A hunter may follow?','animal tracks','a ship’s waterline','a cloud of seed vapor','追踪动物足迹可发生于狩猎。'),Q('hunter',3,1,'Hunter is formed from?','hunt plus an agent suffix','humidity plus a number','hull plus a color ending','hunter 表示执行 hunt 的人。'),Q('hunter',4,1,'Which person is a hunter in this sense?','someone pursuing wild game','someone cataloging novels','someone repairing a bicycle','该义是猎捕动物的人。')]);
P('hunting','hunting 可指追逐并猎捕野生动物的活动，也可指认真寻找某物。',C('hunting.s2','租房搜寻','After weeks of hunting for an affordable apartment, Sam found a place near the train station.','经过数周寻找价格合适的公寓，萨姆终于在火车站附近找到了一处住处。','After weeks of hunting / for an affordable apartment / Sam found a place / near the train station.','hunting for 表示持续寻找；after weeks 强调搜寻持续了一段时间。','他一直在寻找公寓而非狩猎动物，符合 s2。'),M('Sam described hunting for an apartment but never searched listings, visited homes, or asked anyone about rentals.','Sam searched listings and visited homes while hunting for an apartment.','完全没有寻找行为不符合 hunting 的搜寻义。'),[Q('hunting',1,1,'Hunting as a sport involves?','pursuing and killing wild animals','reading poetry aloud','adding water vapor to air','s1 指狩猎活动。'),Q('hunting',2,2,'A job-hunting campaign is?','a search for work','a hunt for animals','a type of whale watching','hunting 可比喻认真寻找。'),Q('hunting',3,1,'Which phrase uses the sport sense?','wildlife hunting season','apartment hunting online','hunting for a lost book','sport/season 语境表达狩猎活动。'),Q('hunting',4,2,'Which phrase uses the search sense?','hunting for a missing document','hunting deer in the forest','a hunter’s rifle','hunting for a document 表示搜寻。')]);
P('hurdle','hurdle 可指赛跑中跨越的栏架或需要克服的障碍，也可作动词表示跨越、克服。',C('hurdle.s2','项目管理','Limited storage was the main hurdle, so the team rented a nearby room before moving the equipment.','储存空间有限是主要障碍，因此团队在搬运设备前租用了附近的一间房。','Limited storage was the main hurdle / so the team rented a nearby room / before moving the equipment.','hurdle 在此为比喻义“障碍”；so 引出团队解决问题的行动。','空间不足阻碍项目进展，符合 s2。'),M('The report called storage a hurdle even though there was unlimited room and no obstacle to the project.','The report called storage an advantage because plenty of room was available.','充足空间不会构成项目障碍。'),[Q('hurdle',1,1,'A hurdle in a race is?','a frame runners jump over','a long-distance shelter','a type of color','赛跑栏架是 hurdle。'),Q('hurdle',2,2,'A financial hurdle is?','a problem that must be overcome','a prize for finishing first','a simple decoration','hurdle 可比喻难关。'),Q('hurdle',3,3,'To hurdle an obstacle is to?','jump over or overcome it','make it more humid','write a funny story','动词 hurdle 表示跨越或克服。'),Q('hurdle',4,2,'Lack of access can be a hurdle because it?','blocks progress','guarantees success','means a hundred people','障碍会阻碍进展。')]);
P('hurl','hurl 可指用力猛投、体育项目中的投掷，也可指大声喊出辱骂或指责。',C('hurl.s3','赛场交流','The spectator began to hurl accusations at the referee, but the steward asked everyone to remain calm.','观众开始大声指责裁判，但工作人员请大家保持冷静。','The spectator began to hurl accusations / at the referee / but the steward asked everyone / to remain calm.','hurl accusations at 表示向某人大声抛出指责；but 引出工作人员的劝阻。','观众大声喊出指责而不是投掷物品，符合 s3。'),M('The spectator hurled accusations by silently writing them in a private notebook and telling nobody.','The spectator shouted accusations at the referee.','完全不说出口的私人笔记不符合大声喊出指责的义项。'),[Q('hurl',1,1,'To hurl a stone is to?','throw it violently','place it gently on a shelf','measure its color','hurl 的 s1 是用力投掷。'),Q('hurl',2,2,'In an athletic event, an athlete may hurl?','a heavy object such as a shot','a poem into a library','a ship across water','s2 指体育投掷项目。'),Q('hurl',3,3,'To hurl insults at someone is to?','shout insulting words at them','give them a quiet compliment','write a private note only','hurl 可指大声说出辱骂。'),Q('hurl',4,4,'A hurl in baseball may refer to?','a strong throw','a bird’s song','a humid climate','名词义可指用力投球或投掷。')]);
P('hurricane','hurricane 指伴有极强风力的热带风暴，也可比喻猛烈的冲击或风暴般事物。',C('hurricane.s1','防灾准备','Before the hurricane reached the coast, residents followed evacuation notices and moved inland to designated shelters.','飓风抵达海岸前，居民遵照疏散通知前往内陆指定避难点。','Before the hurricane reached the coast / residents followed evacuation notices / and moved inland / to designated shelters.','hurricane 指强烈热带风暴；before 从句表明疏散发生在风暴抵达前。','风暴登陆前疏散符合 s1；例句强调安全准备。'),M('The forecast called the event a hurricane even though it was a calm, cloudless day with no strong winds.','The forecast called the event a clear, calm day without a storm.','没有强风的平静天气不符合 hurricane 的风暴义。'),[Q('hurricane',1,1,'A hurricane is?','a powerful tropical storm','a small freshwater animal','a calm dry afternoon','hurricane 指强烈热带风暴。'),Q('hurricane',2,2,'A hurricane of criticism means?','a violent rush of criticism','a gentle compliment','a measured amount of humidity','比喻义表示猛烈袭来的事物。'),Q('hurricane',3,1,'People may move inland before a hurricane to?','reach safer shelter','increase the storm’s strength','find a seed husk','提前疏散可避开风暴危险。'),Q('hurricane',4,1,'Strong winds are a feature of a?','hurricane','hummus','hummingbird','强风是飓风的特征。')]);
P('hurry','hurry 可表示迅速行动，也可表示催促别人、行动上的急迫或急于做某事。',C('hurry.s2','出发准备','The guide hurried the group toward the bus because the last ferry was due to leave in ten minutes.','由于末班渡轮十分钟后就要开，导游催促大家赶往公交车。','The guide hurried the group / toward the bus / because the last ferry / was due to leave in ten minutes.','hurry someone 表示催促某人；because 引出催促的原因。','导游促使队伍加快行动，符合 s2。'),M('The guide hurried the group by telling them to slow down and take as long as they liked.','The guide urged the group to move faster because departure was near.','要求放慢并不限时与催促加快相反。'),[Q('hurry',1,1,'To hurry to the station is to?','move or act quickly','stay still for hours','make the air humid','hurry 可表示迅速行动。'),Q('hurry',2,2,'To hurry someone is to?','urge them to act faster','ask them to remain still','make them feel hungry','hurry 可作使役动词表示催促。'),Q('hurry',3,3,'There is no hurry means?','there is no need to act quickly','everyone must run at once','a hurricane is coming','名词 hurry 表示急迫、匆忙。'),Q('hurry',4,4,'In casual speech, “I’m in a hurry to leave” expresses?','eagerness to leave soon','complete indifference about leaving','a belief about humanism','hurry 可表示急于做某事。')]);
P('hurt','hurt 可表示造成身体疼痛、感到疼痛、伤害感情、损害事物，也可作名词指痛苦或创伤。',C('hurt.s3','人际沟通','His blunt comment hurt her feelings, so he apologized and asked how he could make things right.','他直率的话伤害了她的感情，于是他道歉并询问怎样才能弥补。','His blunt comment hurt her feelings / so he apologized / and asked how / he could make things right.','hurt someone’s feelings 表示伤害某人的感情；so 引出道歉这一结果。','评论使她难过，符合情感受伤义 s3。'),M('He said the remark hurt her feelings but also claimed she felt entirely respected and not upset by it.','He said the remark hurt her feelings and made her upset.','完全没有难过或被冒犯，与情感受伤义相矛盾。'),[Q('hurt',1,1,'To hurt someone’s arm is to?','injure it or cause physical pain','make it more popular','remove its outer shell','s1 指身体受伤或疼痛。'),Q('hurt',2,2,'If your knee hurts, it?','feels painful','has a strong desire','is a tropical storm','s2 表示感到疼痛。'),Q('hurt',3,3,'A careless remark may hurt someone by?','making them upset or offended','increasing air moisture','helping them feel understood','s3 指伤害感情。'),Q('hurt',4,4,'A policy can hurt a small business if it?','harms or damages its prospects','makes it more successful','gives it a compliment','hurt 可比喻损害事物。')]);
P('hurtle','hurtle 可指失控般地高速移动，也可指用力投掷某物。',C('hurtle.s1','交通安全','A loose cart began to hurtle down the sloped driveway, so the caretaker moved people out of its path.','一辆松脱的手推车开始沿倾斜车道飞速冲下，管理员便让人们避开它的路线。','A loose cart began to hurtle / down the sloped driveway / so the caretaker moved people / out of its path.','hurtle 描述物体失控般高速移动；so 引出避险措施。','手推车沿斜坡快速冲行，符合 s1。'),M('The cart hurtled down the slope while remaining perfectly motionless beside the door.','The cart remained still beside the door instead of hurtling down the slope.','静止不动与高速冲行不相容。'),[Q('hurtle',1,1,'A vehicle that hurtles past is moving?','very fast and seemingly out of control','slowly and carefully','without moving at all','hurtle 的 s1 指高速、似乎失控地移动。'),Q('hurtle',2,2,'To hurtle an object across a room is to?','throw it with force','place it gently on a table','humidify the room','hurtle 也可表示用力投掷。'),Q('hurtle',3,1,'Which sentence uses hurtle in the fast-motion sense?','The sled hurtled down the hill.','She hurtled the book softly onto the desk.','The air hurtled with moisture.','sled hurtled down 描述高速滑下。'),Q('hurtle',4,1,'A hurtling object may be dangerous because it?','moves rapidly and is hard to control','is always perfectly still','is made of water vapor','高速失控的物体可能造成危险。')]);
P('husband','husband 通常指某人的男性配偶；旧用法中作动词表示节省、谨慎使用资源。',C('husband.s1','家庭安排','Her husband arranged to pick up the children after work, and they agreed to share the school run.','她的丈夫安排下班后接孩子，两人商定轮流接送上学。','Her husband arranged to pick up the children / after work / and they agreed / to share the school run.','husband 作名词指丈夫；her 表示其与女性配偶的关系，arranged to 引出安排。','该词直接指她的男性配偶，符合 s1。'),M('She introduced her husband as her married female sibling rather than her spouse.','She introduced her husband as her male spouse.','husband 指丈夫，不是女性兄弟姐妹。'),[Q('husband',1,1,'A woman’s husband is?','the man she is married to','her employer','a type of whale','husband 的常见名词义是丈夫。'),Q('husband',2,2,'To husband resources in older usage is to?','use them carefully and economically','waste them rapidly','make them more humid','旧动词义表示节省使用。'),Q('husband',3,1,'Which phrase uses the noun sense?','her husband came home','they husbanded their supplies','the husbandry was careful','her husband 是名词“丈夫”。'),Q('husband',4,2,'Which phrase reflects the older verb sense?','husband the remaining budget','marry a husband','a husband’s coat','动词 husband 可指谨慎使用预算。')]);
P('husbandry','husbandry 可指农事及家畜饲养，也可指对土地、资金等资源的谨慎管理。',C('husbandry.s1','畜牧实践','Good animal husbandry includes reliable shelter, clean water, and regular veterinary care for the herd.','良好的畜牧管理包括为畜群提供可靠的住所、清洁饮水和定期兽医护理。','Good animal husbandry includes reliable shelter / clean water / and regular veterinary care / for the herd.','animal husbandry 指照料和饲养家畜；includes 列出其组成实践。','例句描述照料畜群，符合 s1。'),M('The farm described its husbandry as livestock care but provided no shelter, water, or attention to the animals.','The farm described its husbandry as poor because it failed to care for the animals.','完全不照料动物不能称为良好的畜牧管理。'),[Q('husbandry',1,1,'Animal husbandry concerns?','care and breeding of farm animals','writing humorous stories','measuring color hues','畜牧义指家畜照料与饲养。'),Q('husbandry',2,2,'Careful husbandry of land means?','managing it responsibly','leaving it unmanaged','turning it into a whale','s2 指对土地等资源的谨慎管理。'),Q('husbandry',3,1,'Which task is animal husbandry?','providing a herd with veterinary care','cataloging classical literature','measuring a hurricane','照护畜群是畜牧实践。'),Q('husbandry',4,2,'In the resource-management sense, husbandry is close to?','stewardship','wastefulness','hurling','谨慎管理与 stewardship 接近。')]);
P('husk','husk 指种子外面的干燥外壳，也可作动词表示去掉外壳。',C('husk.s1','谷物加工','The mill separated the dry husk from the grain before the kernels were stored.','磨坊在储存谷粒前将干燥外壳与谷粒分离。','The mill separated the dry husk / from the grain / before the kernels / were stored.','husk 在此作名词，指种子或谷物的干燥外壳；from 表示分离对象。','被剥离的干燥谷物外层符合 s1。'),M('The worker called the soft inner kernel the husk and identified the dry outer cover as the edible grain.','The worker called the dry outer cover the husk and the inner part the kernel.','husk 指干燥外层，不是里面的谷粒。'),[Q('husk',1,1,'A husk is the?','dry outer covering of a seed','soft center of a fruit','body of a ship','husk 指种子干燥外壳。'),Q('husk',2,1,'When grain is husked, what happens?','its outer covering is removed','it is made into a hurricane','it gains a hundredfold weight','动词 husk 可指去壳。'),Q('husk',3,1,'Which item has a husk?','a seed with a dry outer cover','a cloud of water vapor','a literary style','种子可有干燥外壳。'),Q('husk',4,1,'The husk is usually located?','on the outside of a seed','inside the ship’s cabin','in the air as humidity','husk 是种子的外层。')]);
P('hustle','hustle 可表示催促某人、匆忙移动或工作，也可指忙碌喧闹的活动。',C('hustle.s2','车站场景','Even before sunrise, the station was full of hustle as vendors opened their stalls and commuters hurried to work.','天还没亮，车站就已忙碌喧闹起来，摊贩开始营业，通勤者匆匆赶去上班。','Even before sunrise / the station was full of hustle / as vendors opened their stalls / and commuters hurried to work.','hustle 在此作名词，表示忙碌的喧闹；as 引出同时发生的活动。','摊贩和通勤者交织的繁忙场景符合 s2。'),M('The station was full of hustle because it was empty, silent, and no one was moving or working.','The station was quiet because it was empty and no one was moving or working.','空无一人、寂静与忙碌喧闹相反。'),[Q('hustle',1,1,'To hustle a group toward the exit is to?','urge them to move quickly','ask them to remain still','make them more humid','动词义可指催促、赶着移动。'),Q('hustle',2,2,'The hustle of a busy market is its?','lively, noisy activity','complete silence','dry seed covering','名词义指忙碌喧闹的活动。'),Q('hustle',3,1,'A worker hustling to finish a task is?','working quickly and busily','sleeping through the day','studying a whale','hustle 可描述匆忙工作。'),Q('hustle',4,2,'Which place might have a lot of hustle?','a crowded station at rush hour','an empty silent room','a motionless boat in a museum','繁忙车站常有忙碌喧闹景象。')]);
P('hut','hut 指简陋的小房屋或遮蔽物，也可指营地、工地等处的临时建筑。',C('hut.s2','野外营地','The survey crew stored its tools in a temporary hut beside the construction site.','勘测队把工具存放在工地旁的一间临时棚屋里。','The survey crew stored its tools / in a temporary hut / beside the construction site.','hut 在此指工地旁的临时建筑；temporary 修饰 hut，表明用途和期限。','工地旁的临时棚屋符合 s2。'),M('The crew stored its tools in a hut that was a permanent glass skyscraper in the city center.','The crew stored its tools in a temporary hut beside the work site.','玻璃摩天楼不是简陋的临时棚屋。'),[Q('hut',1,1,'A hut is usually?','a small, simple shelter','a huge office tower','a kind of tropical storm','hut 指简陋小屋。'),Q('hut',2,2,'A site hut is often?','a temporary building at a work site','a permanent palace','a seed’s inner kernel','hut 也指工地或营地的临时房。'),Q('hut',3,1,'Which building could be called a hut?','a small basic shelter in a forest','a large luxury hotel','a university library complex','简易林间遮蔽处可称 hut。'),Q('hut',4,2,'Why might a survey team use a hut?','to keep tools at a temporary site','to house a whole city','to measure a hue','工地临时房可用于存工具。')]);
P('hybrid','hybrid 可指不同物种杂交产生的生物、不同事物的混合体，也可作形容词表示混合型。',C('hybrid.s3','交通技术','The fleet added hybrid buses that combine an electric motor with a conventional engine to reduce fuel use in town.','车队增添了混合动力公交车，将电动机与传统发动机结合，以减少市区燃料消耗。','The fleet added hybrid buses / that combine an electric motor / with a conventional engine / to reduce fuel use in town.','hybrid 作形容词表示结合两种类型；that 从句解释动力系统构成。','公交车结合电动机和传统发动机，符合 s3。'),M('The brochure called a bus hybrid even though it used only one type of motor and combined no systems.','The brochure called a bus conventional because it used only a single motor system.','没有结合不同类型系统不符合 hybrid 的“混合型”义。'),[Q('hybrid',1,1,'A hybrid plant may be?','bred from two different species','a bird that flies backward','a tropical storm','生物义指由不同物种培育的杂交生物。'),Q('hybrid',2,2,'A hybrid design is?','a mixture of two different things','a single unchanged type','a dry outer seed covering','hybrid 可表示不同事物的混合体。'),Q('hybrid',3,3,'A hybrid car typically combines?','two types of power system','a hull and a bird','a hundred colors','形容词义指结合两种类型。'),Q('hybrid',4,3,'Which phrase uses hybrid as an adjective?','hybrid-electric bus','a hybrid of two recipes','a hybrid between two plant species','hybrid-electric 在此修饰 bus。')]);
P('hydra','hydra 可指淡水中的小型管状水螅，也可比喻越解决越增生、难以根除的问题。',C('hydra.s2','城市治理','Officials found that the illegal dumping problem behaved like a hydra: closing one site led to several new ones.','官员发现，非法倾倒问题像九头蛇一样难以根除：关闭一个地点后又冒出好几个新地点。','Officials found / that the illegal dumping problem behaved like a hydra / closing one site / led to several new ones.','hydra 在此作比喻，指越处理越增生的难题；冒号后解释比喻。','关闭一处却增加多个新点，符合 s2 的“难除之祸”。'),M('The report called the problem a hydra even though each solution permanently ended it and no new cases appeared.','The report said the problem was easily solved because each intervention ended it permanently.','不会增生且容易根除的问题与比喻义 hydra 不符。'),[Q('hydra',1,1,'A hydra in biology is a?','small freshwater animal with tentacles','large tropical bird','dry plant husk','hydra 可指淡水水螅。'),Q('hydra',2,2,'A problem described as a hydra?','multiplies when attempts are made to remove it','disappears after one simple step','is a shade of blue','比喻义指难以根除且会增生的问题。'),Q('hydra',3,1,'A biological hydra lives in?','fresh water','a ship’s engine','a dry desert only','该动物是淡水生物。'),Q('hydra',4,2,'Which situation resembles a hydra problem?','closing one illegal site creates several new ones','one repair permanently fixes the sole fault','a clear problem is solved once','一个问题处理后反而增生，符合比喻。')]);
P('hydrate','hydrate 可指含有结合水的化合物，也可作动词表示使身体或物质吸收水分。',C('hydrate.s2','运动恢复','After the long practice, the coach reminded the team to hydrate by drinking water and taking a shaded rest.','长时间训练后，教练提醒队员喝水并在阴凉处休息以补充水分。','After the long practice / the coach reminded the team to hydrate / by drinking water / and taking a shaded rest.','hydrate 作动词表示补充水分；by drinking 说明具体方式。','喝水是帮助身体补水的方式，符合 s2。'),M('The coach told the players to hydrate by avoiding all fluids after a hot practice.','The coach told the players to hydrate by drinking water after practice.','避免饮水会妨碍补水，不是 hydrate。'),[Q('hydrate',1,1,'A chemical hydrate is a compound in which?','water is bound to another substance','all water has been removed','two birds are combined','hydrate 有化学义，指结合水的化合物。'),Q('hydrate',2,2,'To hydrate after exercise is to?','take in water','remove moisture from the body','throw a ball forcefully','动词 hydrate 可指补水。'),Q('hydrate',3,2,'Which action can help someone hydrate?','drinking water','avoiding all fluids','running faster in the sun','饮水可以补充水分。'),Q('hydrate',4,1,'The noun related to hydration is?','hydrate','hurdle','humanist','hydrate 与 hydration 同词族。')]);
P('hydration','hydration 指身体摄入水分的过程，也可指化学结合水的作用。',C('hydration.s1','运动健康','The instructor built short water breaks into the hike to support hydration during the warm afternoon.','下午天气暖和，指导员在徒步途中安排了短暂饮水休息，以帮助补充水分。','The instructor built short water breaks into the hike / to support hydration / during the warm afternoon.','hydration 是名词，指补水过程；to support 表示安排饮水休息的目的。','徒步时饮水有助于身体摄入水分，符合 s1。'),M('The plan claimed to support hydration by forbidding participants from drinking any water.','The plan supported hydration by scheduling water breaks.','禁止饮水无法支持补水。'),[Q('hydration',1,1,'Hydration can mean?','the body’s taking in of water','removing all water from the body','a tropical storm','hydration 指身体补水。'),Q('hydration',2,1,'A water break during a hike supports?','hydration','hurling','humbug','饮水休息帮助补充水分。'),Q('hydration',3,1,'In chemistry, hydration can involve?','water binding to a substance','a dry seed shell falling off','a whale surfacing','该词也可指化学结合水。'),Q('hydration',4,1,'Hydration is a?','noun for a process involving water','verb meaning to shame publicly','plural for humans','hydration 是名词。')]);
P('hydraulic','hydraulic 源于希腊语 hydor（水），形容由液体压力驱动或操控的装置。',C('hydraulic.s1','工程检修','The mechanic used a hydraulic lift to raise the bus, relying on pressurized fluid rather than a hand crank.','机械师使用液压升降机抬起公交车，靠的是受压液体而非手摇曲柄。','The mechanic used a hydraulic lift / to raise the bus / relying on pressurized fluid / rather than a hand crank.','hydraulic 修饰 lift，表示以液体压力工作的；rather than 对比驱动方式。','升降机利用受压液体作动力，符合 s1。'),M('The garage called the lift hydraulic although it worked only through a hand crank and contained no pressurized fluid.','The garage called the lift mechanical because it worked through a hand crank alone.','没有液体压力驱动的设备不符合 hydraulic 的定义。'),[Q('hydraulic',1,1,'A hydraulic device is operated by?','pressure from a liquid','a person’s sense of humor','dry seed coverings','hydraulic 指液体压力驱动。'),Q('hydraulic',2,1,'A hydraulic lift may use?','pressurized fluid','a bird’s wings','a hue chart','液压升降机使用受压液体。'),Q('hydraulic',3,1,'Hydraulic comes from a word associated with?','water','fire alone','literature','其词源含义与水相关。'),Q('hydraulic',4,1,'Which system is hydraulic?','one moved by oil pressure','one operated only by a hand crank','one made of dry wood and no fluid','液压系统依靠液体压力。')]);
P('hydrocarbon','hydrocarbon 由 hydro-（此处指氢）和 carbon 组合命名，指分子只含氢、碳的有机化合物。',C('hydrocarbon.s1','基础化学','Methane is the simplest hydrocarbon because each molecule contains carbon and hydrogen atoms and no other elements.','甲烷是最简单的碳氢化合物，因为每个分子只含碳原子和氢原子，不含其他元素。','Methane is the simplest hydrocarbon / because each molecule contains carbon and hydrogen atoms / and no other elements.','hydrocarbon 是化学名词；because 从句说明甲烷符合其元素组成定义。','分子只含碳和氢，准确符合 s1。'),M('The lab classified a compound containing only carbon, oxygen, and nitrogen as a hydrocarbon.','The lab classified a compound containing only carbon and hydrogen as a hydrocarbon.','hydrocarbon 的分子只含氢和碳，加入氧、氮即不符合定义。'),[Q('hydrocarbon',1,1,'A hydrocarbon molecule contains?','only hydrogen and carbon','only oxygen and nitrogen','water and calcium only','hydrocarbon 只含氢与碳。'),Q('hydrocarbon',2,1,'Which compound is a hydrocarbon by this definition?','one made of carbon and hydrogen only','one containing carbon, oxygen, and chlorine','one made only of sodium','须只由碳、氢构成。'),Q('hydrocarbon',3,1,'Methane is described here as?','the simplest hydrocarbon','a type of whale','a hydraulic pump','甲烷是最简单的碳氢化合物。'),Q('hydrocarbon',4,1,'The prefix hydro- in the term points to?','hydrogen','hunting','humanity','hydrocarbon 中 hydro- 指氢相关成分。')]);
P('hydrodynamic','hydrodynamic 由 hydro-（水、液体）和 dynamic（运动、动力）构成，指液体运动及其作用力。',C('hydrodynamic.s1','船舶设计','The engineer tested the hull’s hydrodynamic shape to see how smoothly water would flow around it.','工程师测试船体的流体动力外形，以观察水流能否平顺地绕过船身。','The engineer tested the hull’s hydrodynamic shape / to see / how smoothly water would flow / around it.','hydrodynamic 修饰 shape，说明该形状与液体流动及作用力有关；to see 引出测试目的。','测试水流绕船体的方式，符合 s1。'),M('The report called the study hydrodynamic even though it examined only how dry soil crumbled in air.','The report called the study aerodynamic because it examined air flow rather than liquid motion.','hydrodynamic 关注液体运动，不是干土或空气流动。'),[Q('hydrodynamic',1,1,'Hydrodynamic research concerns?','how liquids move and exert forces','how dry seeds are stored','how humor changes over time','hydrodynamic 研究液体运动与作用力。'),Q('hydrodynamic',2,1,'A hydrodynamic hull is designed with attention to?','water flowing around it','a bird’s backward flight','the amount of classroom humor','船体形状会影响周围水流。'),Q('hydrodynamic',3,1,'The first element hydro- points to?','water or liquid','a hundred','a human scholar','hydro- 指水或液体。'),Q('hydrodynamic',4,1,'Which topic is hydrodynamic?','forces on a moving boat in water','a poem’s rhyme scheme','humidity in an empty room only','水中船体受力属于流体动力学问题。')]);
P('hydroelectric','hydroelectric 由 hydro-（水）与 electric（电）构成，形容利用流动水能发电的。',C('hydroelectric.s1','能源介绍','The hydroelectric station generates electricity as water flows through turbines beside the dam.','这座水力发电站利用水流经过大坝旁的涡轮机来发电。','The hydroelectric station generates electricity / as water flows / through turbines / beside the dam.','hydroelectric 修饰 station，表示利用水能发电；as 引出发电时的水流过程。','流动水驱动涡轮机产生电力，符合 s1。'),M('The brochure called a diesel-only generator hydroelectric even though it used no moving water.','The brochure called a diesel-only generator fuel-powered rather than hydroelectric.','只靠柴油、未利用流动水能的发电机不是 hydroelectric。'),[Q('hydroelectric',1,1,'Hydroelectric power comes from?','energy of moving water','dry seed shells','a person’s mood','hydroelectric 指利用流动水能发电。'),Q('hydroelectric',2,1,'A hydroelectric dam typically uses water to turn?','turbines','hummingbird wings','a printing press','水流可驱动涡轮机发电。'),Q('hydroelectric',3,1,'The word combines ideas of water and?','electricity','literature','hunting','hydroelectric 结合水能与电力。'),Q('hydroelectric',4,1,'Which facility is hydroelectric?','a station powered by a river’s flow','a generator running only on diesel','a warehouse with no power source','利用河流发电的站点属于水力发电。')]);
P('hydrogen','hydrogen 是最轻的化学元素，常态为无色气体，也可指作为燃料使用的氢。',C('hydrogen.s2','能源报道','The report describes hydrogen as a fuel for a demonstration bus and notes that the project is evaluating storage and safety systems.','报道将氢描述为示范公交车的燃料，并说明项目正在评估储存与安全系统。','The report describes hydrogen as a fuel / for a demonstration bus / and notes / that the project is evaluating storage and safety systems.','hydrogen 在此指燃料用途的氢，as 后说明其用途；that 从句交代评估内容。','氢用于公交车能源示范，符合 s2。'),M('The article called hydrogen a fuel but described it as a colourless metal heavier than every other element.','The article described hydrogen as a colourless gas and the lightest chemical element.','氢是最轻的元素，常态为无色气体，不是最重的金属。'),[Q('hydrogen',1,1,'Hydrogen is?','the lightest chemical element','the heaviest metal','a small freshwater animal','hydrogen 是最轻的化学元素。'),Q('hydrogen',2,2,'Hydrogen used to power a vehicle is?','hydrogen fuel','a seed husk','a tropical storm','s2 指作为燃料使用的氢。'),Q('hydrogen',3,1,'At ordinary conditions, hydrogen is described as a?','colourless gas','blue liquid','solid fruit covering','词条描述它是无色气体。'),Q('hydrogen',4,2,'A bus project evaluating hydrogen may study?','fuel storage and safety','how to humidify fruit','a bird’s feeding habits','燃料项目会评估储存和安全。')]);
P('hydrogeologist','hydrogeologist 由 hydro-（水）与 geologist（地质学家）构成，指研究水在土壤和岩石中如何移动的人。',C('hydrogeologist.s1','地下水调查','A hydrogeologist measured water levels in several wells to map how the aquifer changes after heavy rain.','一位水文地质学家测量了几口井的水位，以绘制含水层在大雨后的变化。','A hydrogeologist measured water levels / in several wells / to map how the aquifer changes / after heavy rain.','hydrogeologist 指研究地下水与地质的人；to map 表明测量的目的。','井水位变化可用于研究水在地层中的移动，符合 s1。'),M('The article called a specialist in musical comedy a hydrogeologist even though she never studied water or rock.','The article called a specialist in groundwater movement a hydrogeologist.','不研究水在土壤、岩石中移动的人不符合该职业定义。'),[Q('hydrogeologist',1,1,'A hydrogeologist studies?','how water moves through soil and rock','how comedy is written','how ships are painted','hydrogeologist 研究水在土壤和岩石中的移动。'),Q('hydrogeologist',2,1,'Which task fits a hydrogeologist?','mapping an aquifer from well measurements','writing a hymn for a choir','removing seed husks','研究含水层与井水位符合该职业。'),Q('hydrogeologist',3,1,'The ending -geologist identifies a specialist in?','geology','humor','hunting','geologist 指地质学家。'),Q('hydrogeologist',4,1,'A hydrogeologist’s work may inform?','groundwater management','the spelling of humourous','a race hurdle design only','地下水研究可服务资源管理。')]);
P('hydrographic','hydrographic 形容与绘制海岸、水深和水流图表有关的水道测量工作。',C('hydrographic.s1','海图制作','The hydrographic survey recorded coastal depths and currents so that updated navigation charts could be prepared.','这次水道测量记录了海岸水深和水流，以便编制更新后的航海图。','The hydrographic survey recorded coastal depths and currents / so that updated navigation charts / could be prepared.','hydrographic 修饰 survey，表示水道测量；so that 从句说明测量目的。','测量海岸水深与水流以制图，符合 s1。'),M('The team called a land-only census hydrographic although it collected no information about coasts, depths, or currents.','The team called the coastal depth-and-current survey hydrographic.','只统计陆地人口而不测量水域，与 hydrographic 无关。'),[Q('hydrographic',1,1,'A hydrographic survey studies?','coasts, water depths, and currents','the grammar of old poems','dry seed coverings','hydrographic 指水道测量。'),Q('hydrographic',2,1,'Hydrographic information can help prepare?','navigation charts','humorous sketches','a list of human resources','测量结果可用于编制航海图。'),Q('hydrographic',3,1,'Which measurement is hydrographic?','depths along a coastline','humidity inside a book','the height of a hurdle','沿岸水深测量属于水道测量。'),Q('hydrographic',4,1,'The work is especially concerned with?','mapping marine areas','writing about humanism','managing farm animals','水道测量关注水域与海岸制图。')]);
P('hydrologic','hydrologic 形容与水循环、陆地水体及水文学研究相关的事物。',C('hydrologic.s1','流域研究','The hydrologic model estimates how much rain will flow into the reservoir after a week of storms.','这套水文模型估算一周暴雨后有多少雨水会流入水库。','The hydrologic model estimates / how much rain will flow / into the reservoir / after a week of storms.','hydrologic 修饰 model，表示研究陆地水循环与水体的模型；how much 引出估算内容。','模型预测降雨径流与水库水量，符合 s1。'),M('The report described a model of planetary orbit alone as hydrologic even though it tracked no water cycle or land water.','The report described a model of river flow and rainfall as hydrologic.','只研究行星轨道且不研究水，不符合水文学义。'),[Q('hydrologic',1,1,'A hydrologic model concerns?','the water cycle and water on land','the life cycle of a whale','a style of comedy','hydrologic 与水循环和陆地水有关。'),Q('hydrologic',2,1,'A hydrologic forecast might estimate?','rainfall flowing into a reservoir','how many jokes a writer can tell','the color of a ship','预测径流入库量是水文分析。'),Q('hydrologic',3,1,'Hydrologic is an?','adjective','noun for a whale','verb meaning to embarrass','hydrologic 是形容词。'),Q('hydrologic',4,1,'A closely related field is?','hydrology','humanism','hunting','hydrologic 与 hydrology（水文学）相关。')]);
P('hydrological','hydrological 指与水的分布和流动有关的，常用于描述研究、数据或过程。',C('hydrological.s1','水资源规划','The hydrological data show that the northern basin stores more groundwater during the wet season.','水文数据表明，北部流域在雨季储存的地下水更多。','The hydrological data show / that the northern basin stores more groundwater / during the wet season.','hydrological 修饰 data，表示与水分布、流动有关；that 从句呈现数据结论。','地下水的储存变化属于水的分布和运动，符合 s1。'),M('The report called data on bird plumage hydrological even though they described no water distribution or movement.','The report called rainfall and groundwater records hydrological data.','鸟羽颜色数据不涉及水的分布或流动。'),[Q('hydrological',1,1,'Hydrological data concern?','the distribution and movement of water','the humor of a writer','the shape of a bird’s wings','hydrological 与水的分布和运动有关。'),Q('hydrological',2,1,'Which record is hydrological?','groundwater levels over time','a list of comedy awards','a catalog of seed husks','地下水位记录属于水文数据。'),Q('hydrological',3,1,'A hydrological study might compare?','wet-season and dry-season river flow','two spellings of a joke','two types of animal fur','季节性河流流量比较属于水文研究。'),Q('hydrological',4,1,'Hydrological is closest in meaning to?','related to hydrology','related to humor','related to hunting','hydrological 与水文学相关。')]);
P('hydronic','hydronic 描述通过管道循环热水或冷水的系统，常用于建筑供暖或制冷。',C('hydronic.s1','建筑设备','The apartment uses a hydronic heating system that circulates warm water through pipes beneath the floor.','这套公寓采用液体循环供暖系统，让温水在地板下的管道中循环。','The apartment uses a hydronic heating system / that circulates warm water / through pipes / beneath the floor.','hydronic 修饰 heating system；that 从句说明热水如何在管道中循环。','系统以管道循环热水供暖，符合 s1。'),M('The contractor called a fan-only air system hydronic even though no heated or chilled water circulated through pipes.','The contractor called the fan-only system air-based rather than hydronic.','没有水在管道中循环的风机系统不符合 hydronic 定义。'),[Q('hydronic',1,1,'A hydronic system circulates?','heated or chilled water through pipes','dry grain through a mill','a bird around a flower','hydronic 系统通过管道循环热水或冷水。'),Q('hydronic',2,1,'A hydronic heating system may warm a room using?','water pipes beneath the floor','a tropical storm','a ship’s outer shell','地板下循环热水的管道可供暖。'),Q('hydronic',3,1,'Hydronic is most closely associated with?','water-based building heating or cooling','hunting wild animals','writing humorous essays','它常用于建筑水循环供暖或制冷。'),Q('hydronic',4,1,'Which feature would make a system hydronic?','water moving through pipes','air moving only through a fan','no heating or cooling equipment','水在管道中循环是关键特征。')]);
P('hydroponic','hydroponic 由 hydro-（水）与表示劳动、栽培的词根组合，形容不用土壤而在营养液中种植的。',C('hydroponic.s1','温室栽培','The farm grows hydroponic lettuce in nutrient-rich water, allowing roots to receive minerals without soil.','农场在富含营养的水中种植水培生菜，让根部无需土壤也能获得矿物质。','The farm grows hydroponic lettuce / in nutrient-rich water / allowing roots to receive minerals / without soil.','hydroponic 修饰 lettuce，表示水培；allowing 说明该种植方式如何供给矿物质。','植物在营养液而非土壤中生长，符合 s1。'),M('The grower called the crop hydroponic even though every plant grew directly in ordinary soil.','The grower called the soil-free crop hydroponic because its roots grew in nutrient solution.','完全在土壤中栽培不符合 hydroponic 的水培义。'),[Q('hydroponic',1,1,'Hydroponic plants grow?','in nutrient-rich water instead of soil','only inside a dry seed shell','inside a ship’s hull','hydroponic 指在营养水溶液中种植。'),Q('hydroponic',2,1,'What supplies minerals to a hydroponic plant?','nutrient solution','a hurricane','a hymn','营养液为水培植物提供矿物质。'),Q('hydroponic',3,1,'Which crop is hydroponic?','lettuce grown without soil in water','lettuce grown directly in a field soil','a printed picture of lettuce','无土营养液种植属于水培。'),Q('hydroponic',4,1,'The prefix hydro- refers here to?','water','one hundred','a human scholar','水培名称中的 hydro- 指水。')]);
P('hydroponically','hydroponically 是副词，表示以水培方式、在营养液而非土壤中种植。',C('hydroponically.s1','城市农业','The rooftop farm grows herbs hydroponically in shallow channels filled with circulating nutrient solution.','屋顶农场在装有循环营养液的浅槽中以水培法种植香草。','The rooftop farm grows herbs hydroponically / in shallow channels / filled with circulating nutrient solution.','hydroponically 修饰 grows，说明种植方法；filled with 补充说明浅槽内容。','香草在循环营养液中、无土生长，符合 s1。'),M('The farm said it grew basil hydroponically while planting every root in dry field soil and using no nutrient solution.','The farm said it grew basil conventionally in soil rather than hydroponically.','直接在土壤中种植不是水培。'),[Q('hydroponically',1,1,'Plants grown hydroponically are grown?','in nutrient solution rather than soil','only in dry air','inside a seed shell','hydroponically 指在营养液中而不是土壤里种植。'),Q('hydroponically',2,1,'In “grow tomatoes hydroponically,” the adverb describes?','how the tomatoes are grown','the tomatoes’ color only','how much the tomatoes weigh','副词修饰 grow，说明种植方式。'),Q('hydroponically',3,1,'Which setup grows herbs hydroponically?','roots in circulating nutrient water','roots planted in ordinary soil','seeds stored in a dry box','营养液栽培属于水培。'),Q('hydroponically',4,1,'The related adjective is?','hydroponic','hydraulic','hydrographic','hydroponically 源自形容词 hydroponic。')]);
P('hydropower','hydropower 指利用下落或流动水能产生的电力或动力。',C('hydropower.s1','清洁能源','The mountain region supplies hydropower to nearby towns by channeling river water through turbines.','山区通过引导河水流经涡轮机，为附近城镇提供水电。','The mountain region supplies hydropower / to nearby towns / by channeling river water / through turbines.','hydropower 指水流能产生的电力；by 引出发电方式。','河水驱动涡轮机产生电力，符合 s1。'),M('The company called electricity from a diesel generator hydropower even though it used no falling or flowing water.','The company called electricity from a river turbine hydropower.','柴油发电没有利用水流能量。'),[Q('hydropower',1,1,'Hydropower is generated from?','falling or flowing water','dry seed coverings','a writer’s sense of humor','hydropower 由水流或落水的能量产生。'),Q('hydropower',2,1,'A river turbine can produce?','hydropower','humbleness','a hymn','涡轮机利用河流动力发电。'),Q('hydropower',3,1,'Hydropower is a form of?','energy','a person’s spouse','a tropical storm','hydropower 是一种能源。'),Q('hydropower',4,1,'Which source is hydropower?','a dam’s moving water','a diesel engine alone','a hand-cranked lift','大坝水流可提供水电。')]);
P('hydrosphere','hydrosphere 由 hydro-（水）和 sphere（圈层）构成，指地球上所有水体的总和，包括海洋、河流、地下水、冰和水汽。',C('hydrosphere.s1','地球科学','The lesson describes the hydrosphere as including ocean water, glaciers, groundwater, rivers, and water vapor.','课程把水圈描述为包括海水、冰川、地下水、河流和水汽。','The lesson describes the hydrosphere / as including ocean water, glaciers, groundwater, rivers, / and water vapor.','hydrosphere 是地球科学名词；as including 后列举水圈的组成。','列举了地球上的主要水体及水汽，符合 s1。'),M('The textbook defined the hydrosphere as Earth’s rocks and metals while excluding every form of water.','The textbook defined the hydrosphere as Earth’s water in oceans, ice, rivers, and other forms.','水圈指所有水体，不是岩石金属，也不能排除水。'),[Q('hydrosphere',1,1,'The hydrosphere includes?','Earth’s oceans, rivers, ice, groundwater, and water vapor','only rocks and metals','only the planet’s dry air','hydrosphere 指地球水圈。'),Q('hydrosphere',2,1,'Which belongs to the hydrosphere?','groundwater','a dry mountain rock','a bird’s feather','地下水属于水圈。'),Q('hydrosphere',3,1,'The word combines hydro- with sphere, referring to?','Earth’s water system','a kind of poem','a ship’s outer body','词义是地球水体构成的圈层。'),Q('hydrosphere',4,1,'Water vapor is included in the hydrosphere?','Yes, it is part of Earth’s water.','No, the term includes only rocks.','No, it means all living animals.','水汽也是水圈的一部分。')]);
P('hydrothermal','hydrothermal 由 hydro-（水）和 thermal（热）构成，形容与地球内部热水或蒸汽有关的地质活动。',C('hydrothermal.s1','地质考察','The geologists sampled minerals near a hydrothermal vent where hot water rose through cracks in the ocean floor.','地质学家在海底裂缝中热水上涌的热液喷口附近采集了矿物样本。','The geologists sampled minerals / near a hydrothermal vent / where hot water rose / through cracks in the ocean floor.','hydrothermal 修饰 vent，说明喷口与热水有关；where 从句描述热液活动。','地球内部热水从海底裂缝上涌，符合 s1。'),M('The survey labeled a cold, dry cave with no underground water or steam a hydrothermal vent.','The survey labeled a vent releasing hot underground water hydrothermal.','没有热水或蒸汽的干燥洞穴不符合 hydrothermal 义。'),[Q('hydrothermal',1,1,'Hydrothermal activity involves?','hot water or steam from within Earth','cold dry air only','a funny writing style','hydrothermal 指地球内部热水或蒸汽。'),Q('hydrothermal',2,1,'A hydrothermal vent may occur?','where hot water rises through the seafloor','inside a dry paper file','on a bird’s wing','热液喷口可位于海底热水上涌处。'),Q('hydrothermal',3,1,'The elements hydro- and thermal point to?','water and heat','wind and humor','soil and cold','hydrothermal 结合水与热。'),Q('hydrothermal',4,1,'Which site is hydrothermal?','a hot-water vent on the ocean floor','a cold dry room','a river with no geothermal heat','地热热水喷口符合该词义。')]);
P('hydrotropism','hydrotropism 由 hydro-（水）和 -tropism（趋性、生长反应）构成，指植物因水分刺激而弯曲生长。',C('hydrotropism.s1','植物生理','The roots showed hydrotropism by bending toward the moist side of the soil chamber.','根系表现出向水性，朝土壤箱较湿润的一侧弯曲生长。','The roots showed hydrotropism / by bending toward the moist side / of the soil chamber.','hydrotropism 指植物对水分的定向生长反应；by 引出观察到的表现。','根朝水分较多的一侧弯曲，符合 s1。'),M('The experiment recorded hydrotropism when the roots bent away from moisture solely in response to light.','The experiment recorded phototropism when the shoots bent toward light.','只对光线作出的反应不是向水性 hydrotropism。'),[Q('hydrotropism',1,1,'Hydrotropism is a plant’s growth response to?','water','sound','a human voice','hydrotropism 是植物对水分的生长反应。'),Q('hydrotropism',2,1,'Roots showing hydrotropism may bend toward?','moist soil','a dry region with no water','a written poem','根会朝水分较多处生长。'),Q('hydrotropism',3,1,'The suffix -tropism relates to?','a directional growth response','a seed’s dry cover','a hundredfold amount','-tropism 表示趋性或定向生长反应。'),Q('hydrotropism',4,1,'A plant root’s response to water is?','hydrotropism','hustle','humpback','向水性就是 hydrotropism。')]);
P('hydroxyapatite','hydroxyapatite 是一种结晶态磷酸钙矿物，构成并使骨骼和牙齿坚硬。',C('hydroxyapatite.s1','口腔健康','Tooth enamel contains hydroxyapatite crystals, which give the hard outer surface much of its mineral strength.','牙釉质含有羟基磷灰石晶体，它们为坚硬外层提供了大部分矿物强度。','Tooth enamel contains hydroxyapatite crystals / which give the hard outer surface / much of its mineral strength.','hydroxyapatite 是矿物名词；which 从句说明晶体对牙釉质的作用。','该晶体存在于牙齿硬组织中并提供矿物强度，符合 s1。'),M('The lab identified hydroxyapatite as a soft gas found only in the atmosphere and absent from teeth and bones.','The lab identified hydroxyapatite as a crystalline calcium phosphate found in hard tissues such as bone and teeth.','该物质是骨和牙中的结晶磷酸钙，不是大气中的软气体。'),[Q('hydroxyapatite',1,1,'Hydroxyapatite is a crystalline form of?','calcium phosphate','hydrogen gas','water vapor','hydroxyapatite 是结晶态磷酸钙。'),Q('hydroxyapatite',2,1,'Hydroxyapatite helps harden?','bone and teeth','a paper hymn','a ship’s hull','它使骨骼和牙齿坚硬。'),Q('hydroxyapatite',3,1,'Tooth enamel contains?','hydroxyapatite crystals','a tropical storm','a human resources office','牙釉质含有该晶体。'),Q('hydroxyapatite',4,1,'Hydroxyapatite is best described as?','a mineral in hard tissues','a soft atmospheric gas','a kind of bird','它是骨牙硬组织中的矿物成分。')]);
P('hygiene','hygiene 指为预防疾病而保持清洁的实践，也可指研究健康与清洁的卫生学。',C('hygiene.s1','食品安全','The kitchen’s hygiene rules require staff to wash their hands and sanitize counters between food-preparation tasks.','厨房卫生规范要求员工洗手，并在不同食品准备工作之间消毒台面。','The kitchen’s hygiene rules require staff / to wash their hands / and sanitize counters / between food-preparation tasks.','hygiene 在此指预防疾病的清洁实践；require 后接 staff to do 两项动作。','洗手与消毒台面用于保持清洁、防止疾病，符合 s1。'),M('The kitchen claimed to follow good hygiene while leaving raw-food spills on counters and never washing hands.','The kitchen improved hygiene by cleaning spills and washing hands between tasks.','不洗手、不清洁台面与良好卫生实践相反。'),[Q('hygiene',1,1,'Good hygiene helps?','keep things clean to prevent disease','make a storm more powerful','remove every human value','hygiene 指保持清洁以预防疾病。'),Q('hygiene',2,2,'The science of health and cleanliness is?','hygiene','hull','hurry','hygiene 也可指卫生学。'),Q('hygiene',3,1,'Which practice supports hygiene?','washing hands before food preparation','leaving contaminated surfaces uncleaned','sharing unwashed utensils','清洁手部和表面能保持卫生。'),Q('hygiene',4,1,'The closest topic to hygiene is?','disease prevention through cleanliness','hydrodynamic boat design','humorous writing','卫生实践与疾病预防相关。')]);
P('hymn','hymn 源自希腊语 hymnos，指用于宗教崇拜或礼仪的歌曲。',C('hymn.s1','合唱活动','The congregation sang a quiet hymn together before the service began.','礼拜开始前，会众一起轻声唱了一首赞美诗。','The congregation sang a quiet hymn together / before the service began.','hymn 是宗教歌曲；before 从句说明唱诗发生的时间。','礼拜中的集体歌唱符合 s1。'),M('The program called a secular instrumental drum solo a hymn even though it had no religious words or purpose.','The program called the religious song a hymn.','没有宗教用途或歌曲内容的鼓独奏不符合 hymn 的定义。'),[Q('hymn',1,1,'A hymn is usually?','a religious song','a type of ship','a tropical storm','hymn 指宗教歌曲、赞美诗。'),Q('hymn',2,1,'A congregation may sing a hymn during?','a religious service','a chemistry exam only','a ship repair','赞美诗常在宗教礼仪中演唱。'),Q('hymn',3,1,'Which item is a hymn?','a song of praise used in worship','a humorous footnote','a weather chart','用于礼拜的赞美歌曲是 hymn。'),Q('hymn',4,1,'Hymn comes from a Greek word for?','a song of praise','a water pipe','a seed covering','该词源与歌曲有关。')]);
P('hype','hype 指夸大某事优点或规模的宣传、炒作；该词更早的来源尚不确定。',C('hype.s1','产品评论','The reviewer warned readers not to trust the hype surrounding the new phone until independent battery tests were published.','评论者提醒读者，在独立电池测试结果公布前，不要轻信围绕这款新手机的炒作。','The reviewer warned readers / not to trust the hype / surrounding the new phone / until independent battery tests were published.','hype 是表示夸大宣传的名词；not to trust ... until 表示等待证据再判断。','评论建议不要轻信宣传，而要看独立测试，符合 s1。'),M('The advertisement called its claims hype even though every feature had been independently verified and none was exaggerated.','The advertisement described the claims as verified facts rather than hype.','经过独立核实且没有夸大的陈述不属于炒作。'),[Q('hype',1,1,'Hype is publicity that?','makes something sound better or bigger than it is','reports every fact without exaggeration','measures water depth','hype 指夸大宣传。'),Q('hype',2,1,'A product surrounded by hype may have?','exaggerated publicity','no public attention of any kind','a hundredfold smaller name','炒作会夸大产品宣传。'),Q('hype',3,1,'Why wait for independent tests before trusting the hype?','to check claims against evidence','to make the advertising louder','to avoid learning what was tested','独立测试有助核验宣传主张。'),Q('hype',4,1,'Which is hype?','promising impossible results to attract buyers','publishing careful verified measurements','quietly correcting a factual typo','夸大不实的承诺属于 hype。')]);
P('hyper','hyper 是非正式形容词，表示因紧张精力过剩而过度兴奋、难以安静；其词根 hyper- 源于希腊语“超过、过度”。',C('hyper.s1','课堂观察','After the sugary party drinks, the children seemed hyper and found it difficult to sit quietly through the story.','喝过派对上的含糖饮料后，孩子们显得异常兴奋，很难安静地听完整个故事。','After the sugary party drinks / the children seemed hyper / and found it difficult / to sit quietly through the story.','hyper 作非正式形容词，描述过度兴奋、精力旺盛；found it difficult to 后接动作。','孩子们兴奋得难以安静坐着，符合 s1。'),M('The teacher called the exhausted, quiet class hyper even though no student showed nervous energy or excitement.','The teacher called the exhausted, quiet class calm rather than hyper.','疲惫安静、没有过剩精力与 hyper 的含义相反。'),[Q('hyper',1,1,'A hyper child is often?','full of nervous energy and unable to stay calm','very sleepy and quiet','a type of mineral','hyper 描述过度兴奋、难以安静。'),Q('hyper',2,1,'“The puppy is hyper” informally means it?','is unusually energetic and restless','is asleep all afternoon','has a ship’s hull','口语中 hyper 指精力旺盛、坐不住。'),Q('hyper',3,1,'The Greek element hyper- means roughly?','over or beyond','under or below','together with','hyper- 表示超过、过度。'),Q('hyper',4,1,'Which classroom looks hyper?','students bouncing around and unable to sit still','students quietly reading after a long day','an empty room','坐不住、精力过剩符合 hyper。')]);

})();
